// W-5 / R-N9 by construction: the single fetch below targets
// `POST /repos/{owner}/{repo}/pulls/{n}/reviews` with `event: "COMMENT"`,
// HARD-CODED. There is no code path that sends APPROVE / REQUEST_CHANGES, that
// merges, pushes a branch, or opens a PR. The committee recommends; humans gate.
//
// The repo (owner/repo) is read from the in-repo project.json; the github.token
// is injected per-fire from the active project's credential bag and read here
// from GITHUB_TOKEN. The verdict body is read from a FILE so multi-line /
// Unicode prose can't be mangled by shell quoting.
//
// Usage:
//   GITHUB_TOKEN=<credentials['github.token'].token> \
//     node workforce/skills/legal-amendment-review-committee/post-review.mjs \
//       --project asp-cloud --pr 42 --body-file /tmp/larc-verdict-42.md
//
// Exit codes:
//   0  — review created (HTTP 200)
//   1  — bad args / project.json missing / body-file unreadable or empty
//   2  — endpoint rejected (auth / 4xx)
//   3  — network / unexpected error

import { readFileSync } from "node:fs";
import { fileURLToPath, pathToFileURL } from "node:url";
import { dirname, join } from "node:path";

const GH_API = "https://api.github.com";
const HERE = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = join(HERE, "..", "..", "..");

function arg(name) {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 && i + 1 < process.argv.length ? process.argv[i + 1] : undefined;
}

// Resolve { owner, repo } from workforce/projects/{id}/project.json:github.
function projectRepo(repoRoot, projectId) {
  const path = join(repoRoot, "workforce", "projects", projectId, "project.json");
  let json;
  try {
    json = JSON.parse(readFileSync(path, "utf8"));
  } catch {
    throw new Error(`project.json unreadable for project "${projectId}" at ${path}`);
  }
  const gh = json.github;
  if (!gh || typeof gh.owner !== "string" || typeof gh.repo !== "string") {
    throw new Error(`project "${projectId}" has no github.{owner,repo} — not an external git project`);
  }
  return { owner: gh.owner, repo: gh.repo };
}

async function main() {
  const projectId = arg("project");
  const prNumber = arg("pr");
  const bodyFile = arg("body-file");
  const token = process.env.GITHUB_TOKEN;

  if (!projectId) die(1, "--project <id> is required");
  if (!prNumber || !/^\d+$/.test(prNumber)) die(1, "--pr <number> is required (positive integer)");
  if (!bodyFile) die(1, "--body-file <path> is required");
  if (!token) die(2, "GITHUB_TOKEN env is required (from credentials['github.token'].token)");

  let owner, repo, body;
  try {
    ({ owner, repo } = projectRepo(REPO_ROOT, projectId));
  } catch (e) {
    die(1, e.message);
  }
  try {
    body = readFileSync(bodyFile, "utf8");
  } catch {
    die(1, `body-file unreadable: ${bodyFile}`);
  }
  if (body.trim().length === 0) {
    die(1, "body-file is empty — refusing to post an empty committee verdict (W-4)");
  }

  let res;
  try {
    res = await fetch(`${GH_API}/repos/${owner}/${repo}/pulls/${prNumber}/reviews`, {
      method: "POST",
      headers: {
        authorization: `Bearer ${token}`,
        accept: "application/vnd.github+json",
        "content-type": "application/json",
        "x-github-api-version": "2022-11-28",
        "user-agent": "kohuehara-workforce",
      },
      // event is COMMENT, hard-coded: a recommendation, never a merge-gating verdict.
      body: JSON.stringify({ body, event: "COMMENT" }),
    });
  } catch (e) {
    die(3, `network error: ${e instanceof Error ? e.message : String(e)}`);
  }
  if (res.status === 200) {
    const json = await res.json().catch(() => ({}));
    console.log(`larc-post: committee verdict posted to ${owner}/${repo}#${prNumber} (review ${json.id ?? "?"})`);
    process.exit(0);
  }
  const text = await res.text().catch(() => "");
  die(res.status < 500 ? 2 : 3, `POST review → ${res.status}: ${text.slice(0, 300)}`);
}

function die(code, msg) {
  console.error(`larc-post: ${msg}`);
  process.exit(code);
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? "").href) {
  main().catch((e) => die(3, e instanceof Error ? e.message : String(e)));
}

export { projectRepo };

#!/usr/bin/env node
// Wire maya's `legal-amendment-review-committee` binding via
// PATCH /agents/maya (ADR-0007: bindings are DDB config, agents-api is the
// single writer — each PATCH is validated (R8 against the SKILL# rows) and
// lands its own AUDIT item; write = live, no deploy).
//
// One agent, one binding: maya (the committee chair) ← the
// legal-amendment-review-committee skill, executor=claude-code-routine,
// scheduler=manual (non-periodic; the amendment under review is supplied
// per invocation — there is NO cron). Mirrors the shape documented in
// workforce/docs/routines/legal-amendment-review-committee.md.
//
// PREREQ (fail-loud if unmet): the PR adding workforce/skills/
// legal-amendment-review-committee must be MERGED and the data-plane deploy
// finished — wf-seed-skills creates the SKILL#legal-amendment-review-
// committee row (owners=[maya]) post-deploy, and the R8 write-time check
// validates this binding against that row. Running before the seed 422s
// with R8-binding-skill-exists (no partial write).
//
// Idempotent: maya's existing bindings are preserved (append-only —
// binding_idx is load-bearing); if the committee skill is already bound,
// this skips rather than duplicating it.
//
// Usage:
//   node workforce/skills/legal-amendment-review-committee/wire-binding.mjs --dry-run
//   aws-vault exec <profile> -- node workforce/skills/legal-amendment-review-committee/wire-binding.mjs

import { spawnSync } from "node:child_process";

const API_BASE = (
  process.env.WF_AGENTS_API_BASE ??
  "https://sjhikazsf9.execute-api.us-west-2.amazonaws.com/prod"
).replace(/\/+$/, "");
const REGION = process.env.AWS_REGION ?? "us-west-2";
const DRY_RUN = process.argv.includes("--dry-run");

const AGENT = "maya";
const SKILL = "legal-amendment-review-committee";

// claude-code-routine + manual is the declarative-pending shape (the
// routine_spec is the load-bearing artefact; operator-invoked today). No
// cron: this committee convenes on demand, not on a schedule.
const BINDING = {
  skill: SKILL,
  executor: "claude-code-routine",
  trigger: { scheduler: "manual" },
  routine_spec: `workforce/docs/routines/${SKILL}.md`,
  project_id: "asp-cloud",
  note: "VP-tier+ committee; reviews asp-cloud governance amendments; comment-only (W-5/R-N9).",
};

function curlJson(method, path, body) {
  const { AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY, AWS_SESSION_TOKEN } = process.env;
  const args = ["-sS", "-X", method, "-H", "content-type: application/json", "-w", "\n%{http_code}", `${API_BASE}${path}`];
  if (method !== "GET") {
    if (!AWS_ACCESS_KEY_ID || !AWS_SECRET_ACCESS_KEY) {
      throw new Error("AWS credentials missing — run under `aws-vault exec <profile> --`");
    }
    args.push("--aws-sigv4", `aws:amz:${REGION}:execute-api`, "--user", `${AWS_ACCESS_KEY_ID}:${AWS_SECRET_ACCESS_KEY}`);
    if (AWS_SESSION_TOKEN) args.push("-H", `x-amz-security-token: ${AWS_SESSION_TOKEN}`);
    args.push("--data-binary", "@-");
  }
  const res = spawnSync("curl", args, { input: method === "GET" ? undefined : JSON.stringify(body), encoding: "utf8" });
  if (res.status !== 0) throw new Error(`curl failed: ${res.stderr}`);
  const out = res.stdout;
  const nl = out.lastIndexOf("\n");
  return { status: Number(out.slice(nl + 1)), json: out.slice(0, nl) ? JSON.parse(out.slice(0, nl)) : undefined };
}

const cur = await (await fetch(`${API_BASE}/agents/${AGENT}`)).json();
if (!Array.isArray(cur.bindings)) {
  console.error(`✗ ${AGENT}: GET returned no bindings[] (agent registered?)`);
  process.exit(1);
}
if (cur.bindings.some((b) => b.skill === SKILL)) {
  console.log(`- ${AGENT}: ${SKILL} already bound, skipped`);
  process.exit(0);
}

// Append-only: existing bindings keep their binding_idx.
const next = [...cur.bindings, BINDING];
if (DRY_RUN) {
  console.log(`[dry-run] ${AGENT}: would PATCH bindings -> +1 (${SKILL} @ manual); total ${next.length}`);
  process.exit(0);
}

const { status, json } = curlJson("PATCH", `/agents/${AGENT}`, { bindings: next });
if (status === 200) {
  console.log(`✓ ${AGENT}: bound ${SKILL} (claude-code-routine + manual; project=asp-cloud)`);
  console.log("Done — write = live (ADR-0007). Invoke the committee on demand; there is no cron.");
} else {
  console.error(`✗ ${AGENT}: HTTP ${status} ${JSON.stringify(json)}`);
  if (status === 422) {
    console.error("  422 usually means the SKILL# row isn't seeded yet (R8-binding-skill-exists) —");
    console.error("  ensure the skill PR is merged AND the data-plane deploy + wf-seed-skills have run.");
  }
  process.exit(1);
}

#!/usr/bin/env node
// Deterministic cohort picker for the memory-curation Cadence (Epic-018
// Story 3). Lists active agents oldest-memory-first and prints the cohort
// this fire should curate, sized so a daily binding re-curates every
// active agent at least weekly as the roster grows:
//
//   cohort_size = max(--cohort-size ?? 5, ceil(active_agents / 7))
//
// Never-curated agents (no memory.body) sort first, keyed by their
// memory.last_updated when present (the empty legacy deck carries one) or
// epoch otherwise. The read is the public roster API — the same
// GET /agents/{slug} detail the runner composes from, so what this script
// sees is exactly what fires see.
//
// Usage:
//   node workforce/skills/memory-curation/pick-cohort.mjs \
//     [--cohort-size 5] [--exclude slug1,slug2]
//   # override host for a non-prod stage: MEMORY_API_BASE=https://.../{stage}
//
// Output (stdout, single JSON object):
//   { cohort: [{slug, last_updated, memory_chars}], active_agents, cohort_size }
//
// Exit codes: 0 ok · 1 bad args · 3 network/API error (fail loud, W-4).

const DEFAULT_API_BASE = "https://sjhikazsf9.execute-api.us-west-2.amazonaws.com/prod";
const API_BASE = (process.env.MEMORY_API_BASE ?? DEFAULT_API_BASE).replace(/\/+$/, "");

function arg(name) {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 && i + 1 < process.argv.length ? process.argv[i + 1] : undefined;
}

const cohortSizeArg = arg("cohort-size");
const baseCohort = cohortSizeArg ? Number(cohortSizeArg) : 5;
if (!Number.isInteger(baseCohort) || baseCohort < 1) {
  console.error(`invalid --cohort-size "${cohortSizeArg}"`);
  process.exit(1);
}
const exclude = new Set(
  (arg("exclude") ?? "").split(",").map((s) => s.trim()).filter(Boolean),
);

async function getJson(path) {
  const res = await fetch(`${API_BASE}${path}`);
  if (!res.ok) throw new Error(`GET ${path} -> HTTP ${res.status}`);
  return res.json();
}

try {
  const list = await getJson("/agents?page_size=100");
  const slugs = (list.items ?? [])
    .map((a) => a.slug)
    .filter((s) => typeof s === "string" && !exclude.has(s));

  const rows = [];
  for (const slug of slugs) {
    // The list view strips profile blocks; the detail carries memory.
    const detail = await getJson(`/agents/${encodeURIComponent(slug)}`);
    if (detail.archived === true) continue;
    const memory = detail.memory ?? {};
    rows.push({
      slug,
      last_updated: typeof memory.last_updated === "string" && memory.last_updated ? memory.last_updated : "1970-01-01",
      memory_chars: typeof memory.body === "string" ? memory.body.length : 0,
    });
  }

  // Oldest curation first; never-curated (epoch/no body) lead. Slug is the
  // deterministic tiebreak so two fires never disagree on order.
  rows.sort((a, b) =>
    a.last_updated === b.last_updated
      ? a.slug.localeCompare(b.slug)
      : a.last_updated.localeCompare(b.last_updated),
  );

  const cohortSize = Math.max(baseCohort, Math.ceil(rows.length / 7));
  console.log(
    JSON.stringify(
      { cohort: rows.slice(0, cohortSize), active_agents: rows.length, cohort_size: cohortSize },
      null,
      2,
    ),
  );
} catch (err) {
  console.error(`pick-cohort failed: ${err instanceof Error ? err.message : String(err)}`);
  process.exit(3);
}

#!/usr/bin/env node
// Deterministic memory writer — invoked by the CCR agent-runner after the
// LLM has *distilled* the revised MEMORY.md. The LLM owns the judgment
// (what the record means); this script owns the structurally-exact write,
// so the "LLM hand-edits JSON and guesses the schema wrong" failure class
// cannot recur (same division as feed-post/post-feed.mjs).
//
// It POSTs to the authenticated `POST /agents/{slug}/memory` endpoint
// (ADR-0020), which re-validates the ADR-0019 content contract and the
// shrink guard server-side before writing the `memory` profile block and
// landing an AUDIT row. The client-side pre-check here exists only to
// fail fast with a named reason before the network round-trip; the server
// copy (lambdas/shared/memory-contract.ts) is the authoritative gate.
//
// Body is read from a FILE (not an arg) so multi-line / Unicode prose
// can't be mangled by shell quoting.
//
// The write TOKEN is injected per-fire
// (credentials['workforce.memory_write_token'].token); the endpoint URL is
// not a secret and is embedded here as this skill's single source of
// truth. Override with MEMORY_API_BASE only for non-prod stages.
//
// Usage:
//   MEMORY_WRITE_TOKEN=<token> \
//     node workforce/skills/memory-curation/update-memory.mjs \
//       --agent freya --body-file /tmp/memory-freya.md [--allow-shrink]
//
// Exit codes:
//   0 — memory written (HTTP 200)
//   1 — bad args / env / body-file unreadable / local contract pre-check
//   2 — endpoint rejected the write (HTTP 422 contract/shrink, 401 auth, 404 slug)
//   3 — network / unexpected error

import { readFileSync } from "node:fs";

const DEFAULT_API_BASE = "https://sjhikazsf9.execute-api.us-west-2.amazonaws.com/prod";
const API_BASE = (process.env.MEMORY_API_BASE ?? DEFAULT_API_BASE).replace(/\/+$/, "");

// Mirrors lambdas/shared/memory-contract.ts (the authoritative server copy).
const MEMORY_BLOCK_MAX_CHARS = 16 * 1024;
const MEMORY_MIN_CHARS = 200;

function arg(name) {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 && i + 1 < process.argv.length ? process.argv[i + 1] : undefined;
}

const token = process.env.MEMORY_WRITE_TOKEN;
const agent = arg("agent");
const bodyFile = arg("body-file");
const allowShrink = process.argv.includes("--allow-shrink");

if (!token) {
  console.error("MEMORY_WRITE_TOKEN env var is required (credentials['workforce.memory_write_token'].token)");
  process.exit(1);
}
if (!agent || !/^[a-z]+$/.test(agent)) {
  console.error(`--agent must be a lowercase slug (got "${agent ?? ""}")`);
  process.exit(1);
}
if (!bodyFile) {
  console.error("--body-file is required");
  process.exit(1);
}

let body;
try {
  body = readFileSync(bodyFile, "utf8");
} catch (err) {
  console.error(`cannot read --body-file ${bodyFile}: ${err.message}`);
  process.exit(1);
}

// Fail-fast local pre-check of the ADR-0019 contract.
const violations = [];
if (!/^# MEMORY — /m.test(body)) violations.push('missing "# MEMORY — <Name> (<Role>)" title');
if (!/Curated:\s*\d{4}-\d{2}-\d{2}/.test(body)) violations.push('missing "Curated: YYYY-MM-DD" token');
if (!/^## Mission anchor$/m.test(body)) violations.push('missing "## Mission anchor" section');
if (body.trim().length < MEMORY_MIN_CHARS) violations.push(`body under ${MEMORY_MIN_CHARS} chars`);
if (body.length > MEMORY_BLOCK_MAX_CHARS) violations.push(`body over the ${MEMORY_BLOCK_MAX_CHARS}-char ceiling`);
if (violations.length > 0) {
  console.error(`memory document fails the ADR-0019 contract locally:\n  - ${violations.join("\n  - ")}`);
  process.exit(1);
}

try {
  const res = await fetch(`${API_BASE}/agents/${encodeURIComponent(agent)}/memory`, {
    method: "POST",
    headers: {
      authorization: `Bearer ${token}`,
      "content-type": "application/json",
    },
    body: JSON.stringify(allowShrink ? { body, allow_shrink: true } : { body }),
  });
  const text = await res.text();
  if (res.status === 200) {
    console.log(`memory written for ${agent}: ${text}`);
    process.exit(0);
  }
  console.error(`endpoint rejected the write for ${agent}: HTTP ${res.status} ${text}`);
  process.exit(res.status === 401 || res.status === 404 || res.status === 422 ? 2 : 3);
} catch (err) {
  console.error(`network error writing memory for ${agent}: ${err instanceof Error ? err.message : String(err)}`);
  process.exit(3);
}

#!/usr/bin/env node
// memory-hygiene/post.mjs — deterministic write for the "memory-hygiene" Cadence,
// invoked by the CCR agent-runner AFTER it has *generated* the content. The LLM
// owns the judgment (body / structured fields); this script owns the
// structurally-exact write so the failure class "LLM hand-edits JSON and
// guesses the schema wrong" cannot recur. Modeled on
// workforce/skills/feed-post/post-feed.mjs — the canonical Cadence write.
//
// It POSTs to an authenticated endpoint with the project-scoped credential
// injected per-fire (credentials['workforce.feed_write_token']). The script does NOT
// touch the repo, does NOT open a PR — the write lands directly in the backing
// store. No human approval gate. Note: this script writes to the FEED only —
// it never writes to any memory/{slug}/ prefix or MEMORY#INDEX row (hygiene
// findings are proposals; curation writes belong to freya's memory-curation).
//
// Body is read from a FILE (not an arg) so multi-line / Unicode prose can't be
// mangled by shell quoting. The write CREDENTIAL is injected per-fire; the
// endpoint URL is NOT a secret and is the single source of truth right here.
//
// Usage:
//   FEED_WRITE_TOKEN=<from credentials['workforce.feed_write_token']> \
//     node workforce/skills/memory-hygiene/post.mjs \
//       --agent <slug> --body-file /tmp/body.md [--skill-version 0.1.0]
//
// Exit codes:
//   0  — written (HTTP 2xx)
//   1  — bad args / env / body-file unreadable
//   2  — endpoint rejected (HTTP 401 auth / 422 validation)
//   3  — network / unexpected error

import { readFileSync } from "node:fs";

// Single source of truth for this Cadence's write endpoint. Override with
// FEED_WRITE_TOKEN_API_URL only for non-prod / dev stages.
const DEFAULT_API_URL = "https://sjhikazsf9.execute-api.us-west-2.amazonaws.com/prod/feed";

function arg(name) {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 && i + 1 < process.argv.length ? process.argv[i + 1] : undefined;
}

const apiUrl = process.env["FEED_WRITE_TOKEN_API_URL"] || DEFAULT_API_URL;
const token = process.env["FEED_WRITE_TOKEN"];
const agent = arg("agent");
const bodyFile = arg("body-file");
const skillVersion = arg("skill-version");

if (!token) { console.error("post.mjs: FEED_WRITE_TOKEN env var is required (from credentials['workforce.feed_write_token'])"); process.exit(1); }
if (!agent) { console.error("post.mjs: --agent <slug> is required"); process.exit(1); }
if (!bodyFile) { console.error("post.mjs: --body-file <path> is required"); process.exit(1); }
if (apiUrl.startsWith("TODO_")) { console.error("post.mjs: DEFAULT_API_URL is still a scaffold placeholder — set the real endpoint"); process.exit(1); }

let body;
try {
  body = readFileSync(bodyFile, "utf8");
} catch (err) {
  console.error(`post.mjs: cannot read --body-file "${bodyFile}": ${err instanceof Error ? err.message : String(err)}`);
  process.exit(1);
}

// W-1 editorial guard (client side; the endpoint should re-run it server side).
// A degraded body fails loud here rather than landing on the backing store.
const ARTEFACTS = ["as an ai", "i apologize", "i'm sorry", "certainly!", "sure, ", "here is the", "here's the"];
const head = body.trimStart().slice(0, 50).toLowerCase();
if (body.trim().length === 0) { console.error("post.mjs: body is empty (W-1)"); process.exit(1); }
if (ARTEFACTS.some((a) => head.startsWith(a))) { console.error(`post.mjs: body opens with an LLM-failure artefact (W-1): "${head}"`); process.exit(1); }

// POST /feed requires a `kind` from the Epic-011 set {reflection, friction,
// improvement, observation}. A memory-hygiene note is beat-noticing — its
// findings are proposals addressed to owners, not writes — so it is ALWAYS
// an observation; the constant lives here (the deterministic layer) so the
// LLM cannot mis-tag it.
const payload = { agent_slug: agent, kind: "observation", body };
if (skillVersion) payload.skill_version = skillVersion;

console.error(`post.mjs: POST ${apiUrl}`);

try {
  const res = await fetch(apiUrl, {
    method: "POST",
    headers: { "content-type": "application/json", authorization: `Bearer ${token}` },
    body: JSON.stringify(payload),
  });
  const text = await res.text().catch(() => "");
  if (res.status >= 200 && res.status < 300) {
    console.log(`post.mjs: written — ${text}`);
    process.exit(0);
  }
  if (res.status === 401 || res.status === 422) {
    console.error(`post.mjs: rejected (HTTP ${res.status}): ${text.slice(0, 400)}`);
    process.exit(2);
  }
  console.error(`post.mjs: unexpected HTTP ${res.status}: ${text.slice(0, 400)}`);
  process.exit(3);
} catch (err) {
  console.error(`post.mjs: fetch failed: ${err instanceof Error ? err.message : String(err)}`);
  process.exit(3);
}

#!/usr/bin/env node
// monthly-report/post.mjs — deterministic write for the "monthly-report" Cadence,
// invoked by the CCR agent-runner AFTER it has *generated* the report markdown.
// The LLM owns the judgment (the letter); this script owns the structurally-exact
// Notion write so the failure class "LLM hand-edits the page JSON and guesses the
// schema wrong" cannot recur. Modeled on article-level2/publish-notion.mjs (the
// canonical W-1-guarded Notion write), with one material difference: a monthly
// report is ~10 letter pages, far past Notion's 100-blocks-per-request cap, so
// this script APPENDS the remainder in 100-block batches instead of silently
// slicing at 100 (a silent cut is exactly the degradation W-1 exists to refuse).
//
// It POSTs a new page into the unified Articles DB using the injected Notion
// integration token, with the dedicated Tags/Category "Monthly Report" so the
// reports are filterable as their own series in the DB and the reader UI.
//
// The CCR session never reads Secrets Manager: NOTION_API_KEY arrives inline
// from the task's `credentials["notion.integration_token"].apiKey`. The target
// DB id is NOT secret (already committed in newsletter/pipeline) — a constant
// below, overridable by NOTION_DB_ID for tests / migrations.
//
// Usage:
//   NOTION_API_KEY="<credentials['notion.integration_token'].apiKey>" \
//     node workforce/skills/monthly-report/post.mjs \
//       --agent maya \
//       --body-file /tmp/monthly-report-body.md \
//       [--abstract-file /tmp/abstract.txt] \
//       [--tags "AI Strategy,Agentic AI"]   # optional extra vocabulary tags
//       [--status published]                # draft|ready|published|archived
//
// Exit codes:
//   0 — page created (all blocks landed)
//   1 — bad args / env / body-file unreadable / no H1 title
//   2 — W-1 editorial guard failed (short body, LLM-artefact prelude, cut-off
//       last line) or auth rejected
//   3 — Notion API / network error (including a failed batch append — the page
//       is then INCOMPLETE and the error says so; do not leave it silently)

import { readFileSync } from "node:fs";
import { isTruncatedMarkdown, lastNonEmptyLine } from "../../../scripts/lib/truncation.mjs";
import { validateTags } from "../../../scripts/lib/tags.mjs";

const NOTION_VERSION = "2022-06-28";
const NOTION_API = "https://api.notion.com/v1";
// Non-secret target DB id (the unified Articles DB). Overridable for tests.
const UNIFIED_DB_ID = process.env.NOTION_DB_ID || "34fd0f0b-e61e-817a-9f6b-dc65b0d5b4cc";
// The dedicated series tag. A constant, not an LLM choice — every monthly
// report carries it so the series is one filter away in the DB / reader UI.
const REPORT_TAG = "Monthly Report";
// A monthly report is a ~10-page letter (≳ 8,000 chars of Japanese prose).
// Anything under this floor is a failed / truncated generation, not a report.
const MIN_BODY_CHARS = 3000;
// Notion hard limits: 100 blocks per create/append request, 2000 chars per
// rich_text element.
const BLOCKS_PER_REQUEST = 100;
const RICH_TEXT_MAX = 2000;
// Notion's code-block language enum doesn't include every fence tag; anything
// unrecognised maps to "plain text" (mermaid IS in the enum and is the one
// this Cadence actually uses). Declared up here because markdownToBlocks runs
// at module top level, before bottom-of-file consts would initialize.
const NOTION_CODE_LANGS = new Set(["mermaid", "javascript", "typescript", "json", "bash", "shell", "python", "sql", "yaml", "markdown", "plain text"]);
const ARTEFACT_PRELUDE =
  /^\s*(as an ai|here is|here's|i apologize|i'm sorry|certainly!|sure,|of course)/i;

function arg(name) {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 && i + 1 < process.argv.length ? process.argv[i + 1] : undefined;
}

const apiKey = process.env.NOTION_API_KEY;
const agent = arg("agent");
const bodyFile = arg("body-file");
const abstractFile = arg("abstract-file");
const tagsArg = arg("tags");
const status = arg("status") ?? "published";

const VALID_STATUS = new Set(["draft", "ready", "published", "archived"]);

if (!apiKey) { console.error("post.mjs: NOTION_API_KEY env var is required (from credentials['notion.integration_token'].apiKey)"); process.exit(1); }
if (!agent) { console.error("post.mjs: --agent <slug> is required"); process.exit(1); }
if (!bodyFile) { console.error("post.mjs: --body-file <path> is required"); process.exit(1); }
if (!VALID_STATUS.has(status)) {
  console.error(`post.mjs: --status must be one of ${[...VALID_STATUS].join("|")} (got "${status}")`);
  process.exit(1);
}

let body;
try {
  body = readFileSync(bodyFile, "utf8");
} catch (err) {
  console.error(`post.mjs: cannot read --body-file "${bodyFile}": ${err instanceof Error ? err.message : String(err)}`);
  process.exit(1);
}

let abstract = "";
if (abstractFile) {
  try {
    abstract = readFileSync(abstractFile, "utf8").trim();
  } catch (err) {
    console.error(`post.mjs: cannot read --abstract-file "${abstractFile}": ${err instanceof Error ? err.message : String(err)}`);
    process.exit(1);
  }
}

// ── W-1 editorial guards (fail loud, do not publish) ───────────────────────
const trimmed = body.trim();
if (trimmed.length < MIN_BODY_CHARS) {
  console.error(`post.mjs: body is ${trimmed.length} chars (< ${MIN_BODY_CHARS}) — refusing to publish a truncated/empty report (W-1)`);
  process.exit(2);
}
if (ARTEFACT_PRELUDE.test(trimmed.slice(0, 50))) {
  console.error("post.mjs: body opens with an LLM-failure prelude — refusing to publish (W-1)");
  process.exit(2);
}
if (isTruncatedMarkdown(trimmed)) {
  console.error(`post.mjs: body looks cut off mid-content (last line: "${lastNonEmptyLine(trimmed)}") — refusing to publish a truncated report (W-1)`);
  process.exit(2);
}

// First `# ` line is the page Title; strip it from the body blocks.
const lines = trimmed.split(/\r?\n/);
const h1Idx = lines.findIndex((l) => /^#\s+\S/.test(l));
if (h1Idx === -1) {
  console.error("post.mjs: body has no `# Title` H1 on its own line — the report format requires one (exit 1)");
  process.exit(1);
}
const title = lines[h1Idx].replace(/^#\s+/, "").trim();
const bodyLines = lines.slice(0, h1Idx).concat(lines.slice(h1Idx + 1));

const blocks = markdownToBlocks(bodyLines.join("\n"));

// Extra vocabulary tags are optional and validated against the flat vocabulary
// (ADR-0003); the dedicated series tag is prepended unconditionally.
const extraTags = validateTags((tagsArg || "").split(",").map((t) => t.trim()).filter(Boolean));
const tags = [REPORT_TAG, ...extraTags.filter((t) => t !== REPORT_TAG)];

// Property names mirror the live unified Articles DB exactly (same contract as
// article-level2/publish-notion.mjs). Type=report marks the row as the
// monthly-report series (the site fetcher renders unknown types as analysis).
const properties = {
  Title: { title: [{ text: { content: title.slice(0, RICH_TEXT_MAX) } }] },
  Author: { rich_text: [{ text: { content: agent } }] },
  Type: { select: { name: "report" } },
  Status: { select: { name: status } },
  Date: { date: { start: new Date().toISOString().slice(0, 10) } },
  Category: { rich_text: [{ text: { content: REPORT_TAG } }] },
  Tags: { multi_select: tags.map((name) => ({ name })) },
};
if (abstract) properties.Abstract = { rich_text: [{ text: { content: abstract.slice(0, RICH_TEXT_MAX) } }] };

async function notion(path, method, payload) {
  const res = await fetch(`${NOTION_API}${path}`, {
    method,
    headers: {
      authorization: `Bearer ${apiKey}`,
      "notion-version": NOTION_VERSION,
      "content-type": "application/json",
    },
    body: JSON.stringify(payload),
  });
  const text = await res.text().catch(() => "");
  return { res, text };
}

try {
  const first = blocks.slice(0, BLOCKS_PER_REQUEST);
  const rest = blocks.slice(BLOCKS_PER_REQUEST);

  const { res, text } = await notion("/pages", "POST", {
    parent: { database_id: UNIFIED_DB_ID },
    properties,
    children: first,
  });
  if (res.status === 401 || res.status === 403) {
    console.error(`post.mjs: auth rejected (HTTP ${res.status}) — project credential bag misconfigured: ${text.slice(0, 400)}`);
    process.exit(2);
  }
  if (!res.ok) {
    console.error(`post.mjs: Notion API error (HTTP ${res.status}): ${text.slice(0, 400)}`);
    process.exit(3);
  }
  let pageId = "";
  let url = "";
  try { ({ id: pageId, url } = JSON.parse(text)); } catch { /* non-JSON ok body */ }

  // Append the remainder in 100-block batches. A failed append leaves the page
  // incomplete — that is a C-1 state, so it must exit loud (3), never 0.
  for (let i = 0; i < rest.length; i += BLOCKS_PER_REQUEST) {
    const batch = rest.slice(i, i + BLOCKS_PER_REQUEST);
    const { res: r2, text: t2 } = await notion(`/blocks/${pageId}/children`, "PATCH", { children: batch });
    if (!r2.ok) {
      console.error(`post.mjs: batch append failed at block ${BLOCKS_PER_REQUEST + i} (HTTP ${r2.status}) — page ${url} is INCOMPLETE: ${t2.slice(0, 400)}`);
      process.exit(3);
    }
  }

  console.log(`post.mjs: created — Author=${agent} Type=report Status=${status} blocks=${blocks.length} "${title}" ${url}`);
  process.exit(0);
} catch (err) {
  console.error(`post.mjs: fetch failed: ${err instanceof Error ? err.message : String(err)}`);
  process.exit(3);
}

// Minimal Markdown → Notion blocks (same dialect as publish-notion.mjs: H1-3,
// bullets, blank-line paragraphs), plus fenced code blocks — a ```mermaid fence
// becomes a Notion code block with language "mermaid", which fetch-notion.mjs
// round-trips back to a fence and the reader renders as an inline figure
// (newsletter/docs/ARTICLE-FIGURES.md). Long text is split across multiple
// rich_text elements instead of sliced at 2000 chars — a report paragraph must
// never be silently cut.
function markdownToBlocks(md) {
  const out = [];
  let para = [];
  let fence = null; // { lang, lines } while inside a ``` fence
  const flushPara = () => {
    if (para.length === 0) return;
    pushText("paragraph", para.join(" "));
    para = [];
  };
  const chunk = (content) => {
    const parts = [];
    for (let i = 0; i < content.length; i += RICH_TEXT_MAX) {
      parts.push({ type: "text", text: { content: content.slice(i, i + RICH_TEXT_MAX) } });
    }
    return parts;
  };
  const pushText = (type, content) => {
    out.push({ object: "block", type, [type]: { rich_text: chunk(content) } });
  };
  for (const raw of md.split(/\r?\n/)) {
    const line = raw.trim();
    if (fence) {
      if (line.startsWith("```")) {
        const lang = NOTION_CODE_LANGS.has(fence.lang) ? fence.lang : "plain text";
        out.push({ object: "block", type: "code", code: { rich_text: chunk(fence.lines.join("\n")), language: lang } });
        fence = null;
      } else {
        fence.lines.push(raw); // raw, not trimmed — indentation is significant
      }
      continue;
    }
    if (line.startsWith("```")) {
      flushPara();
      fence = { lang: line.slice(3).trim().toLowerCase(), lines: [] };
      continue;
    }
    if (line === "") { flushPara(); continue; }
    let m;
    if ((m = line.match(/^###\s+(.+)/))) { flushPara(); pushText("heading_3", m[1]); }
    else if ((m = line.match(/^##\s+(.+)/))) { flushPara(); pushText("heading_2", m[1]); }
    else if ((m = line.match(/^#\s+(.+)/))) { flushPara(); pushText("heading_2", m[1]); }
    else if ((m = line.match(/^[-*]\s+(.+)/))) { flushPara(); pushText("bulleted_list_item", m[1]); }
    else { para.push(line); }
  }
  if (fence) {
    // Unclosed fence = a truncated body that slipped past the guard — fail loud
    // rather than publishing a half-figure (W-1/C-1).
    console.error("post.mjs: unclosed ``` fence in body — refusing to publish (W-1)");
    process.exit(2);
  }
  flushPara();
  return out;
}

// @ts-nocheck — the module under test (collect.mjs) is a dependency-free ESM
// CLI script, not TS. Spawned as a real child process against a FAKE repo
// tree built in a temp dir (mkdtempSync), matching the weekly-project-report /
// pr-autopilot spawn-the-real-script test convention. The GitHub Actions
// fetch is pointed at an unroutable host (127.0.0.1:1) so no live network
// call happens; collect.mjs's own self-observation guard turns that failure
// into a finding rather than a crash — this suite proves that path.
// Discovered by workforce/lambdas/vitest.config.mjs
// (`include: ["../skills/**/*-tests.ts"]`).
import { describe, it, expect } from "vitest";
import { spawnSync } from "node:child_process";
import { mkdtempSync, mkdirSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const SCRIPT = join(__dirname, "collect.mjs");

const STALE_BACKLOG = `## 3. Backlog

<!-- registry:memory-lint columns: ID | Rule | Incidents | Count | Status | Promoted via -->

| ID | Rule | Incidents | Count | Status | Promoted via |
|---|---|---|---|---|---|
| ML-900 | Fixture rule, clearly stale. | (2026-01-01) | 1 | watching | — |
| ML-901 | Fixture rule, fresh. | (2026-07-20) | 1 | watching | — |
`;

function fakeRepoRoot(backlogContent) {
  const dir = mkdtempSync(join(tmpdir(), "oaw-repo-"));
  mkdirSync(join(dir, "docs"), { recursive: true });
  writeFileSync(join(dir, "docs", "memory-lint-backlog.md"), backlogContent, "utf8");
  return dir;
}

function run(args, env) {
  return spawnSync("node", [SCRIPT, ...args], { encoding: "utf8", env: { ...process.env, ...env } });
}

describe("collect.mjs — CLI guard contract + self-observation", () => {
  it("exit 1 when --repo is missing", () => {
    const r = run(["--repo-root", fakeRepoRoot(STALE_BACKLOG)], { GITHUB_TOKEN: "t" });
    expect(r.status).toBe(1);
    expect(r.stderr).toMatch(/--repo/);
  });

  it("exit 1 when GITHUB_TOKEN is missing", () => {
    const r = run(["--repo", "test/test", "--repo-root", fakeRepoRoot(STALE_BACKLOG)], { GITHUB_TOKEN: "" });
    expect(r.status).toBe(1);
    expect(r.stderr).toMatch(/GITHUB_TOKEN/);
  });

  it("exit 3 when the local backlog file itself does not exist (fatal — nothing to read at all)", () => {
    const emptyRoot = mkdtempSync(join(tmpdir(), "oaw-repo-empty-"));
    const r = run(["--repo", "test/test", "--repo-root", emptyRoot], {
      GITHUB_TOKEN: "t",
      GITHUB_API_URL: "http://127.0.0.1:1",
    });
    expect(r.status).toBe(3);
  });

  it("self-observation: a network-unroutable GitHub Actions API becomes a finding, not a crash, and exit stays 0", () => {
    const r = run(["--repo", "test/test", "--repo-root", fakeRepoRoot(STALE_BACKLOG)], {
      GITHUB_TOKEN: "t",
      GITHUB_API_URL: "http://127.0.0.1:1",
    });
    expect(r.status).toBe(0);
    const out = JSON.parse(r.stdout);
    const kinds = out.findings.map((f) => f.kind);
    expect(kinds).toContain("self-observation-failure");
    const selfFinding = out.findings.find((f) => f.kind === "self-observation-failure");
    expect(selfFinding.owner).toBe("petra");
  });

  it("surfaces a stale watching row from the fake repo tree, and does not flag the fresh one", () => {
    const r = run(["--repo", "test/test", "--repo-root", fakeRepoRoot(STALE_BACKLOG)], {
      GITHUB_TOKEN: "t",
      GITHUB_API_URL: "http://127.0.0.1:1",
    });
    expect(r.status).toBe(0);
    const out = JSON.parse(r.stdout);
    const backlogFindings = out.findings.filter((f) => f.kind === "backlog-stale");
    expect(backlogFindings.map((f) => f.key)).toContain("backlog-stale:ML-900");
    expect(backlogFindings.map((f) => f.key)).not.toContain("backlog-stale:ML-901");
  });

  it("a clean-signal repo (no stale rows) still reports the memory-lint-backlog path as a swept surface", () => {
    const cleanBacklog = STALE_BACKLOG.replace("(2026-01-01)", "(2026-07-22)");
    const r = run(["--repo", "test/test", "--repo-root", fakeRepoRoot(cleanBacklog)], {
      GITHUB_TOKEN: "t",
      GITHUB_API_URL: "http://127.0.0.1:1",
    });
    expect(r.status).toBe(0);
    const out = JSON.parse(r.stdout);
    expect(out.sweptSurfaces).toContain("docs/memory-lint-backlog.md");
  });
});

#!/usr/bin/env node
// ops-accountability-watch/collect.mjs — Step 1 of the Cadence's 3-script
// pipeline (collect -> sync-issues -> notify). Reads:
//   (a) recent GitHub Actions run history for this repo (github.token), and
//   (b) docs/memory-lint-backlog.md's own "watching" staleness rule,
// and prints one JSON object of normalized Findings to stdout.
//
// Self-observation (W-4, fail loud not silent): if (a) itself cannot be
// read, that failure becomes a Finding routed to the default owner rather
// than a silent empty sweep or an uncaught throw — a sweep that can't see
// its primary signal is itself worth a human's attention.
//
// Usage:
//   GITHUB_TOKEN=<credentials['github.token'].token> \
//     node collect.mjs --repo refluster/ai-native-article --lookback-hours 26
//
// Exit codes: 0 completed (see JSON for partial-failure findings), 1 bad
// args/env, 3 fatal (couldn't even read the local backlog file).

import { readFileSync } from "node:fs";
import { join } from "node:path";
import {
  extractCiFollowUps,
  latestRunPerWorkflow,
  findStaleWatchingEntries,
} from "./signals.mjs";
import { routeWorkflowOwner, routeGovernanceRegistryOwner } from "./owner-routing.mjs";

const GITHUB_API = process.env.GITHUB_API_URL ?? "https://api.github.com";
const MEMORY_LINT_BACKLOG_REL_PATH = "docs/memory-lint-backlog.md";

function parseArgs(argv) {
  const args = { lookbackHours: 26, repoRoot: process.cwd() };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--repo") args.repo = argv[++i];
    else if (a === "--lookback-hours") args.lookbackHours = Number(argv[++i]);
    else if (a === "--repo-root") args.repoRoot = argv[++i];
  }
  return args;
}

function fail(code, message) {
  console.error(`collect.mjs: ${message}`);
  process.exit(code);
}

// project label for a workflow-based finding — a simplifying default (see
// signals.mjs header): workforce-surface workflows label project:workforce,
// everything else (article/podcast pipelines) labels project:article.
function projectForWorkflow(workflowFile) {
  return /^workforce-/.test(workflowFile) ||
    ["ci.yml", "check-workforce-api-routes.yml", "deploy-workforce-console.yml", "deploy-workforce-data-plane.yml"].includes(
      workflowFile,
    )
    ? "workforce"
    : "article";
}

async function fetchRecentRuns(repo, token, sinceMs) {
  const res = await fetch(`${GITHUB_API}/repos/${repo}/actions/runs?per_page=100`, {
    headers: {
      authorization: `Bearer ${token}`,
      accept: "application/vnd.github+json",
      "x-github-api-version": "2022-11-28",
    },
  });
  if (!res.ok) {
    throw new Error(`GitHub Actions runs fetch failed: HTTP ${res.status}`);
  }
  const body = await res.json();
  return (body.workflow_runs ?? [])
    .map((r) => ({
      workflowFile: String(r.path ?? "").split("/").pop(),
      status: r.status,
      conclusion: r.conclusion,
      htmlUrl: r.html_url,
      createdAt: r.created_at,
      runNumber: r.run_number,
    }))
    .filter((r) => r.workflowFile && new Date(r.createdAt).getTime() >= sinceMs);
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (!args.repo) fail(1, "--repo owner/name is required");
  const token = process.env.GITHUB_TOKEN;
  if (!token) fail(1, "GITHUB_TOKEN env var is required");

  const now = new Date();
  const sinceMs = now.getTime() - args.lookbackHours * 3600_000;
  const sweptSurfaces = [];
  const findings = [];

  // --- Signal 1: CI run history ---
  try {
    const runs = await fetchRecentRuns(args.repo, token, sinceMs);
    const latest = latestRunPerWorkflow(runs);
    sweptSurfaces.push(...latest.map((r) => r.workflowFile));
    const ciFollowUps = extractCiFollowUps(latest);
    for (const run of ciFollowUps) {
      const routed = routeWorkflowOwner(run.workflowFile);
      findings.push({
        kind: "ci-run",
        key: `ci-run:${run.workflowFile}`,
        label: `${run.workflowFile} — ${run.conclusion}`,
        detailLines: [
          `Workflow: \`${run.workflowFile}\``,
          `Conclusion: \`${run.conclusion}\` (run #${run.runNumber})`,
          `Detected within the last ${args.lookbackHours}h sweep window.`,
        ],
        sourceUrl: run.htmlUrl,
        owner: routed.owner,
        ownerReason: routed.reason,
        project: projectForWorkflow(run.workflowFile),
        closeCondition: `Close when the next scheduled/triggered run of \`${run.workflowFile}\` completes with conclusion \`success\`.`,
      });
    }
  } catch (err) {
    // Self-observation: the sweep's own primary signal failed to read —
    // surface that as a finding instead of a silent empty result or crash.
    findings.push({
      kind: "self-observation-failure",
      key: "self-observation:github-actions-runs",
      label: "ops-accountability-watch could not read GitHub Actions run history",
      detailLines: [
        `Error: ${err.message}`,
        "The CI-follow-up half of this sweep did not run this fire; only the local governance-registry signal below is reliable for this fire.",
      ],
      sourceUrl: null,
      owner: routeGovernanceRegistryOwner().owner,
      ownerReason: "the sweep's own read path failed — routes to VP Operations & Reliability by default, never silently dropped",
      project: "workforce",
      closeCondition: "Close when the next fire successfully reads GitHub Actions run history end-to-end.",
    });
  }
  sweptSurfaces.push(MEMORY_LINT_BACKLOG_REL_PATH);

  // --- Signal 2: governance-registry staleness ---
  let backlogText;
  try {
    backlogText = readFileSync(join(args.repoRoot, MEMORY_LINT_BACKLOG_REL_PATH), "utf8");
  } catch (err) {
    fail(3, `could not read ${MEMORY_LINT_BACKLOG_REL_PATH}: ${err.message}`);
  }
  const staleEntries = findStaleWatchingEntries(backlogText, now);
  for (const entry of staleEntries) {
    const routed = routeGovernanceRegistryOwner();
    findings.push({
      kind: "backlog-stale",
      key: `backlog-stale:${entry.id}`,
      label: `${entry.id} stuck in "watching" ${entry.ageDays}d (>= 180d threshold)`,
      detailLines: [
        `Rule: ${entry.rule}`,
        `Opened: ${entry.openedOn} (${entry.ageDays} days ago)`,
        `docs/memory-lint-backlog.md §1's own promotion rule: a "watching" row is promoted, declined, or accepted once it has sat unrevised for >= 6 months.`,
      ],
      sourceUrl: null,
      owner: routed.owner,
      ownerReason: routed.reason,
      project: "workforce",
      closeCondition: `Close when ${entry.id}'s Status in docs/memory-lint-backlog.md changes from \`watching\` to \`accepted\`, \`promoted\`, or \`declined\`.`,
    });
  }

  console.log(JSON.stringify({ generatedAt: now.toISOString(), sweptSurfaces, findings }, null, 2));
  process.exit(0);
}

main().catch((err) => fail(3, err.stack ?? String(err)));

// @ts-nocheck — the module under test (notify.mjs) is a dependency-free ESM
// CLI script, not TS. This suite drives it as a real child process (the
// pr-autopilot / weekly-project-report convention: spawnSync + assert on
// exit code + stderr), so guard behaviour is proven without mocking fetch.
// Discovered by workforce/lambdas/vitest.config.mjs
// (`include: ["../skills/**/*-tests.ts"]`).
import { describe, it, expect } from "vitest";
import { spawnSync } from "node:child_process";
import { mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const SCRIPT = join(__dirname, "notify.mjs");

function tmpFile(name, content) {
  const dir = mkdtempSync(join(tmpdir(), "oaw-"));
  const file = join(dir, name);
  writeFileSync(file, content, "utf8");
  return file;
}

function run(args, env) {
  return spawnSync("node", [SCRIPT, ...args], { encoding: "utf8", env: { ...process.env, ...env } });
}

const CLEAN_FINDINGS = JSON.stringify({ generatedAt: "2026-07-23T00:00:00Z", sweptSurfaces: ["ci.yml"], findings: [] });

describe("notify.mjs — CLI guard contract", () => {
  it("exit 1 when --findings-file is missing", () => {
    const r = run([], { DISCORD_WEBHOOK_URL: "http://127.0.0.1:1" });
    expect(r.status).toBe(1);
    expect(r.stderr).toMatch(/--findings-file/);
  });

  it("exit 1 when --findings-file does not parse as JSON", () => {
    const file = tmpFile("bad.json", "not json");
    const r = run(["--findings-file", file], { DISCORD_WEBHOOK_URL: "http://127.0.0.1:1" });
    expect(r.status).toBe(1);
  });

  it("exit 1 when neither a webhook URL nor a bot token + channel are configured", () => {
    const file = tmpFile("clean.json", CLEAN_FINDINGS);
    const r = run(["--findings-file", file], { DISCORD_WEBHOOK_URL: "", DISCORD_BOT_TOKEN: "", DISCORD_CHANNEL_ID: "" });
    expect(r.status).toBe(1);
    expect(r.stderr).toMatch(/DISCORD_WEBHOOK_URL/);
  });

  it("exit 3 on a network error — guards ran, only the network call itself failed (proves guard order)", () => {
    const file = tmpFile("clean2.json", CLEAN_FINDINGS);
    const r = run(["--findings-file", file], { DISCORD_WEBHOOK_URL: "http://127.0.0.1:1" });
    expect(r.status).toBe(3);
  });
});

#!/usr/bin/env node
// ops-accountability-watch/notify.mjs — Step 3 of the Cadence pipeline: the
// ONE aggregate chat mirror per fire (never one message per finding — see
// workforce/docs/runbooks/chat-notification-policy.md). Webhook is primary
// (it can set a display name via `username`); a bot-token path is wired for
// completeness but is not provisioned for the agent-workforce project today
// — see the README note in workforce/seed/vp-operations/.
//
// Usage:
//   DISCORD_WEBHOOK_URL=<credentials['discord.webhook_url'].url> \
//     node notify.mjs --findings-file /tmp/findings.json --issue-links-file /tmp/links.json \
//       --swept-surfaces-file /tmp/findings.json --mode observation
//
// Exit codes: 0 posted, 1 bad args/env, 2 endpoint rejected (4xx/5xx), 3 network error.

import { readFileSync } from "node:fs";
import { buildNotificationPayload, toDiscordWebhookBody } from "./payload.mjs";

function parseArgs(argv) {
  const args = { mode: "observation" };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--findings-file") args.findingsFile = argv[++i];
    else if (a === "--issue-links-file") args.issueLinksFile = argv[++i];
    else if (a === "--mode") args.mode = argv[++i];
  }
  return args;
}

function fail(code, message) {
  console.error(`notify.mjs: ${message}`);
  process.exit(code);
}

async function postViaWebhook(webhookUrl, body) {
  const res = await fetch(webhookUrl, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(body),
  });
  return res;
}

// Bot-token fallback: posts as the bot's own identity — Discord does not let
// a bot message override its display name per-post (unlike a webhook's
// `username` field), so this path logs that limitation explicitly rather
// than silently pretending parity with the webhook path.
async function postViaBotToken(botToken, channelId, body) {
  console.error(
    "notify.mjs: using discord.bot_token fallback — sender display name is the bot's own identity, NOT overridable per-post (webhook parity is lost on this path).",
  );
  const res = await fetch(`https://discord.com/api/v10/channels/${channelId}/messages`, {
    method: "POST",
    headers: { authorization: `Bot ${botToken}`, "content-type": "application/json" },
    body: JSON.stringify({ embeds: body.embeds }),
  });
  return res;
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (!args.findingsFile) fail(1, "--findings-file is required");

  let findingsEnvelope;
  try {
    findingsEnvelope = JSON.parse(readFileSync(args.findingsFile, "utf8"));
  } catch (err) {
    fail(1, `could not read/parse --findings-file: ${err.message}`);
  }

  let issueLinks = [];
  if (args.issueLinksFile) {
    try {
      issueLinks = JSON.parse(readFileSync(args.issueLinksFile, "utf8"));
    } catch (err) {
      fail(1, `could not read/parse --issue-links-file: ${err.message}`);
    }
  }

  const payload = buildNotificationPayload(
    issueLinks,
    { sweptSurfaces: findingsEnvelope.sweptSurfaces ?? [], mode: args.mode },
    new Date(findingsEnvelope.generatedAt ?? Date.now()),
  );
  const body = toDiscordWebhookBody(payload);

  const webhookUrl = process.env.DISCORD_WEBHOOK_URL;
  const botToken = process.env.DISCORD_BOT_TOKEN;
  const channelId = process.env.DISCORD_CHANNEL_ID;

  let res;
  try {
    if (webhookUrl) {
      res = await postViaWebhook(webhookUrl, body);
    } else if (botToken && channelId) {
      res = await postViaBotToken(botToken, channelId, body);
    } else {
      fail(1, "neither DISCORD_WEBHOOK_URL nor (DISCORD_BOT_TOKEN + DISCORD_CHANNEL_ID) is set");
    }
  } catch (err) {
    fail(3, `network error posting to Discord: ${err.message}`);
  }

  if (!res.ok) {
    fail(2, `Discord rejected the notification: HTTP ${res.status} ${await res.text().catch(() => "")}`);
  }

  console.log(JSON.stringify({ posted: true, mode: payload.mode, status: res.status }));
  process.exit(0);
}

main();

