//
// Usage:
//   FEED_WRITE_TOKEN=<from credentials['workforce.feed_write_token']> \
//     node workforce/skills/performance-refresh/post.mjs \
//       --agent <slug> --body-file /tmp/body.md [--skill-version 0.1.0]
//
// Exit codes:
//   0  — written (HTTP 2xx)
//   1  — bad args / env / body-file unreadable
//   2  — endpoint rejected (HTTP 401 auth / 422 validation)
//   3  — network / unexpected error

import { readFileSync } from "node:fs";

// Single source of truth for this Cadence's write endpoint. Override with
// FEED_WRITE_TOKEN_API_URL only for non-prod / dev stages.
const DEFAULT_API_URL = "https://sjhikazsf9.execute-api.us-west-2.amazonaws.com/prod/feed";

function arg(name) {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 && i + 1 < process.argv.length ? process.argv[i + 1] : undefined;
}

const apiUrl = process.env["FEED_WRITE_TOKEN_API_URL"] || DEFAULT_API_URL;
const token = process.env["FEED_WRITE_TOKEN"];
const agent = arg("agent");
const bodyFile = arg("body-file");
const skillVersion = arg("skill-version");

if (!token) { console.error("post.mjs: FEED_WRITE_TOKEN env var is required (from credentials['workforce.feed_write_token'])"); process.exit(1); }
if (!agent) { console.error("post.mjs: --agent <slug> is required"); process.exit(1); }
if (!bodyFile) { console.error("post.mjs: --body-file <path> is required"); process.exit(1); }
if (apiUrl.startsWith("TODO_")) { console.error("post.mjs: DEFAULT_API_URL is still a scaffold placeholder — set the real endpoint"); process.exit(1); }

let body;
try {
  body = readFileSync(bodyFile, "utf8");
} catch (err) {
  console.error(`post.mjs: cannot read --body-file "${bodyFile}": ${err instanceof Error ? err.message : String(err)}`);
  process.exit(1);
}

// W-1 editorial guard (client side; the endpoint should re-run it server side).
// A degraded body fails loud here rather than landing on the backing store.
const ARTEFACTS = ["as an ai", "i apologize", "i'm sorry", "certainly!", "sure, ", "here is the", "here's the"];
const head = body.trimStart().slice(0, 50).toLowerCase();
if (body.trim().length === 0) { console.error("post.mjs: body is empty (W-1)"); process.exit(1); }
if (ARTEFACTS.some((a) => head.startsWith(a))) { console.error(`post.mjs: body opens with an LLM-failure artefact (W-1): "${head}"`); process.exit(1); }

// POST /feed requires a `kind` from the Epic-011 set {reflection, friction,
// improvement, observation}. A weekly org-metrics note is measurement, not
// friction or proposal — it is ALWAYS an observation; the constant lives
// here (the deterministic layer) so the LLM cannot mis-tag it.
const payload = { agent_slug: agent, kind: "observation", body };
if (skillVersion) payload.skill_version = skillVersion;

console.error(`post.mjs: POST ${apiUrl}`);

try {
  const res = await fetch(apiUrl, {
    method: "POST",
    headers: { "content-type": "application/json", authorization: `Bearer ${token}` },
    body: JSON.stringify(payload),
  });
  const text = await res.text().catch(() => "");
  if (res.status >= 200 && res.status < 300) {
    console.log(`post.mjs: written — ${text}`);
    process.exit(0);
  }
  if (res.status === 401 || res.status === 422) {
    console.error(`post.mjs: rejected (HTTP ${res.status}): ${text.slice(0, 400)}`);
    process.exit(2);
  }
  console.error(`post.mjs: unexpected HTTP ${res.status}: ${text.slice(0, 400)}`);
  process.exit(3);
} catch (err) {
  console.error(`post.mjs: fetch failed: ${err instanceof Error ? err.message : String(err)}`);
  process.exit(3);
}

#!/usr/bin/env node
// performance-refresh/refresh.mjs — the deterministic half of the
// "performance-refresh" Cadence. The LLM owns the judgment (is the surface
// healthy? what changed? what is frozen?); THIS script owns every write, so
// the failure class "the agent hand-rolls an API call and guesses the roll-up
// schema wrong" cannot recur.
//
// What it does, per fire:
//   1. Runs workforce/scripts/build-pr-metrics-github.mjs --publish-ddb for
//      every project scope with a GitHub repo → refreshes PERF#{scope}/PR.
//   2. Runs workforce/scripts/build-repo-performance.mjs --publish-ddb →
//      refreshes PERF#{scope}/REPO for every project + the workforce aggregate.
//   3. Reads back GET /performance and reports, per scope, how fresh each
//      block now is.
//
// It writes a machine-readable JSON report to --out, which the agent reads to
// write its observation. It does NOT post to the feed (that is post.mjs) and
// it does NOT touch the repo or open a PR.
//
// The lifecycle funnel (PERF#{scope}/LIFECYCLE) is NOT refreshed here — that
// is the wf-performance-reducer Lambda's daily job (EventBridge 02:00 UTC).
// This script only *observes* its freshness so a stalled reducer is visible.
//
// AWS: uses the ambient credentials of the execution environment (the CCR
// session's AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY). Region defaults to
// us-west-2, where the data plane and wf/projects/* secrets live.
//
// Usage:
//   node workforce/skills/performance-refresh/refresh.mjs \
//     [--days 90] [--table wf-table-prod] [--region us-west-2] \
//     [--out /tmp/performance-refresh-report.json] [--dry-run]
//
// Exit codes:
//   0 — every refresh leg succeeded
//   2 — at least one leg failed or came back degraded (partial data); the
//       report names which. NOT a hard error: the agent still posts, and
//       saying "X is stale/degraded" is the whole point of the cadence.
//   3 — nothing could be refreshed at all (no scopes, or every leg threw)

import { execFileSync } from "node:child_process";
import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "..");
const PROJECTS_DIR = join(ROOT, "workforce", "projects");
const API_BASE = process.env.WORKFORCE_AGENTS_API_BASE || "https://workforce-api.kohuehara.xyz";

// The console's default view (GET /performance, no project) reads the
// `workforce` scope — which is NOT any project's id, so iterating
// workforce/projects/ alone silently leaves the most-viewed deck frozen.
// (That is exactly how the PR block stayed stuck at 2026-06-23 while the
// per-project scopes looked fine.) The workforce scope tracks the workforce's
// own repo, i.e. the `agent-workforce` project's repo.
const WORKFORCE_SCOPE = "workforce";
const WORKFORCE_SCOPE_SOURCE_PROJECT = "agent-workforce";

function arg(name, fallback) {
  const i = process.argv.indexOf(`--${name}`);
  if (i === -1) return fallback;
  const v = process.argv[i + 1];
  return v && !v.startsWith("--") ? v : true;
}

/** Every project with a GitHub repo — the scopes whose PR block can refresh. */
export function repoScopes(projectsDir = PROJECTS_DIR) {
  if (!existsSync(projectsDir)) return [];
  return readdirSync(projectsDir, { withFileTypes: true })
    .filter((e) => e.isDirectory())
    .map((e) => {
      const file = join(projectsDir, e.name, "project.json");
      if (!existsSync(file)) return null;
      try {
        const p = JSON.parse(readFileSync(file, "utf8"));
        if (!p.github?.owner || !p.github?.repo) return null;
        return { scope: p.id, repo: `${p.github.owner}/${p.github.repo}` };
      } catch {
        return null;
      }
    })
    .filter(Boolean)
    .sort((a, b) => a.scope.localeCompare(b.scope));
}

/** Hours between an ISO timestamp and now; Infinity when unparseable/absent. */
export function ageHours(iso, now = Date.now()) {
  const t = Date.parse(iso ?? "");
  return Number.isFinite(t) ? (now - t) / 3_600_000 : Infinity;
}

/** Classify one block's freshness against the daily cadence. `stale` is the
 *  signal the agent must report — a block that stopped moving is exactly the
 *  failure this cadence exists to make visible. */
export function freshness(updatedAt, { staleHours = 30, now = Date.now() } = {}) {
  const hours = ageHours(updatedAt, now);
  if (!Number.isFinite(hours)) return { state: "missing", hours: null };
  return { state: hours > staleHours ? "stale" : "fresh", hours: Math.round(hours * 10) / 10 };
}

async function secretsClient(region) {
  const { createRequire } = await import("node:module");
  const { pathToFileURL } = await import("node:url");
  const req = createRequire(join(ROOT, "workforce", "lambdas", "package.json"));
  const mod = await import(pathToFileURL(req.resolve("@aws-sdk/client-secrets-manager")).href);
  return { sm: new mod.SecretsManagerClient({ region }), GetSecretValueCommand: mod.GetSecretValueCommand };
}

// AWS error names that mean "this session has no usable identity" rather than
// "this one secret is missing". Distinguishing them is the whole point of H4
// below — see assertAwsIdentity.
const NO_IDENTITY_ERRORS = new Set([
  "CredentialsProviderError",
  "UnrecognizedClientException",
  "InvalidClientTokenId",
  "InvalidSignatureException",
  "ExpiredToken",
  "ExpiredTokenException",
  "AccessDeniedException",
  "AccessDenied",
  "UnauthorizedOperation",
]);

export function isNoIdentityError(err) {
  const name = err?.name ?? "";
  const code = err?.Code ?? err?.$metadata?.httpStatusCode;
  return NO_IDENTITY_ERRORS.has(name) || code === 403;
}

/** H4 (`wf:hana`, #502): a fire with NO ambient AWS identity would otherwise
 *  fail every scope's secret lookup identically and report N separate
 *  "token unresolved" gaps — sending the operator to provision four secrets
 *  that were never the problem. One infrastructure fault must render as ONE
 *  loud line, not N misattributed symptoms, especially in the surface whose
 *  entire job is making faults legible. So: probe the identity ONCE up front
 *  and abort the whole run if it is absent. */
async function assertAwsIdentity(region) {
  const { sm } = await secretsClient(region);
  try {
    const provider = sm.config.credentials;
    const creds = typeof provider === "function" ? await provider() : await provider;
    if (!creds?.accessKeyId) throw Object.assign(new Error("no accessKeyId"), { name: "CredentialsProviderError" });
    return { ok: true };
  } catch (err) {
    return { ok: false, error: err instanceof Error ? `${err.name}: ${err.message}` : String(err) };
  }
}

/** Each project's PAT lives at wf/projects/{id}/github.token — a single
 *  ambient GITHUB_TOKEN would silently 404 on the external repos, so every PR
 *  leg gets its own resolved token injected into the child env. */
async function resolveGithubToken(projectId, region) {
  const { sm, GetSecretValueCommand } = await secretsClient(region);
  const secretId = `wf/projects/${projectId}/github.token`;
  const out = await sm.send(new GetSecretValueCommand({ SecretId: secretId }));
  if (!out.SecretString) throw new Error(`${secretId} has no SecretString`);
  const parsed = JSON.parse(out.SecretString);
  if (typeof parsed?.token !== "string") throw new Error(`${secretId} missing "token" field`);
  return parsed.token;
}

function run(label, file, args, { dry, env }) {
  if (dry) {
    console.error(`[dry-run] would run: ${file} ${args.join(" ")}`);
    return { label, ok: true, dry: true };
  }
  try {
    const stdout = execFileSync("node", [file, ...args], {
      cwd: ROOT,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "pipe"],
      maxBuffer: 64 * 1024 * 1024,
      env: { ...process.env, ...(env ?? {}) },
    });
    return { label, ok: true, tail: stdout.trim().split("\n").slice(-3).join(" | ") };
  } catch (err) {
    // exit 2 from a builder = published but degraded/partial, not a hard fail.
    const degraded = err?.status === 2;
    const stderr = String(err?.stderr ?? err?.message ?? "").trim();
    return {
      label,
      ok: degraded,
      degraded,
      error: degraded ? undefined : stderr.split("\n").slice(-3).join(" | "),
      tail: stderr.split("\n").slice(-3).join(" | "),
    };
  }
}

async function readBack(scope) {
  const url =
    scope === "workforce"
      ? `${API_BASE}/performance`
      : `${API_BASE}/projects/${encodeURIComponent(scope)}/performance`;
  try {
    const res = await fetch(url);
    if (!res.ok) return { scope, reachable: false, status: res.status };
    const s = await res.json();
    return {
      scope,
      reachable: true,
      lifecycle: {
        points: s.lifecycle?.length ?? 0,
        last_date: s.lifecycle?.at?.(-1)?.date ?? null,
      },
      pr: {
        points: s.pr_daily?.length ?? 0,
        last_date: s.pr_daily?.at?.(-1)?.date ?? null,
        total_prs: s.pr_summary?.total_prs ?? 0,
      },
      repo: s.repo
        ? {
            updated_at: s.repo.updated_at,
            freshness: freshness(s.repo.updated_at),
            repos: s.repo.repos ?? [],
            degraded_signals: s.repo.degraded_signals ?? [],
          }
        : null,
    };
  } catch (err) {
    return { scope, reachable: false, error: err instanceof Error ? err.message : String(err) };
  }
}

async function main() {
  const DAYS = String(arg("days", 90));
  const TABLE = String(arg("table", process.env.TABLE_NAME || "wf-table-prod"));
  const REGION = String(arg("region", process.env.AWS_REGION || "us-west-2"));
  const OUT = String(arg("out", "/tmp/performance-refresh-report.json"));
  const dry = process.argv.includes("--dry-run");

  const projectScopes = repoScopes();
  if (projectScopes.length === 0) {
    console.error("refresh.mjs: no project scopes with a GitHub repo — nothing to refresh");
    return 3;
  }
  process.env.AWS_REGION = REGION;

  // The workforce aggregate scope rides on the agent-workforce project's repo
  // and credential, but publishes under scope "workforce" — see the constant's
  // note above; omitting it leaves the console's default deck frozen.
  const wfSource = projectScopes.find((s) => s.scope === WORKFORCE_SCOPE_SOURCE_PROJECT);
  const scopes = [
    ...(wfSource
      ? [{ scope: WORKFORCE_SCOPE, repo: wfSource.repo, tokenProject: WORKFORCE_SCOPE_SOURCE_PROJECT }]
      : []),
    ...projectScopes.map((s) => ({ ...s, tokenProject: s.scope })),
  ];
  if (!wfSource) {
    console.error(
      `refresh.mjs: WARN project "${WORKFORCE_SCOPE_SOURCE_PROJECT}" not found — the workforce-scope PR block will NOT refresh`,
    );
  }

  // H4: one infrastructure fault must not render as N project gaps. Probe the
  // identity once; if it is absent, that IS the finding — fail the whole run
  // with a single line instead of blaming every project's secret in turn.
  if (!dry) {
    const identity = await assertAwsIdentity(REGION);
    if (!identity.ok) {
      const msg =
        `refresh.mjs: no AWS identity available to this fire (${identity.error}) — ` +
        `cannot resolve any wf/projects/*/github.token. This is ONE infrastructure condition, ` +
        `not ${scopes.length} missing project secrets: do not provision secrets in response to this.`;
      console.error(msg);
      writeFileSync(
        OUT,
        `${JSON.stringify(
          {
            generated_at: new Date().toISOString(),
            fatal: "aws-identity-absent",
            detail: identity.error,
            scopes: scopes.map((s) => s.scope),
            legs: [],
            observed: [],
            verdict: { failed: ["aws-identity-absent"], degraded: [], stale_repo_scopes: [], missing_repo_scopes: [], lifecycle_last_dates: {} },
          },
          null,
          2,
        )}\n`,
      );
      return 3;
    }
  }

  const legs = [];

  // 1. PR metrics, per scope (each needs its own repo + its own PAT).
  for (const { scope, repo, tokenProject } of scopes) {
    let token;
    if (!dry) {
      try {
        token = await resolveGithubToken(tokenProject, REGION);
      } catch (err) {
        // Identity was proven present above, so an auth-class error here means
        // it was revoked mid-run — again one fault, not a per-project gap.
        if (isNoIdentityError(err)) {
          console.error(
            `refresh.mjs: AWS identity lost mid-run at scope "${scope}" (${err?.name}) — aborting rather than reporting per-project gaps`,
          );
          return 3;
        }
        // Otherwise: this scope's secret genuinely is not provisioned. A real,
        // reportable gap — never a silent skip that reads as "no activity".
        legs.push({
          label: `pr:${scope}`,
          ok: false,
          error: `token unresolved: ${err instanceof Error ? err.message : String(err)}`,
        });
        continue;
      }
    }
    legs.push(
      run(`pr:${scope}`, join(ROOT, "workforce/scripts/build-pr-metrics-github.mjs"), [
        "--repo", repo,
        "--scope", scope,
        "--days", DAYS,
        "--publish-ddb",
        "--table", TABLE,
      ], { dry, env: token ? { GITHUB_TOKEN: token } : undefined }),
    );
  }

  // 2. Repository activity — one pass writes every scope + the aggregate.
  legs.push(
    run("repo:all", join(ROOT, "workforce/scripts/build-repo-performance.mjs"), [
      "--days", DAYS,
      "--publish-ddb",
      "--table", TABLE,
      "--region", REGION,
    ], { dry }),
  );

  // 3. Read back what the console will actually serve.
  // `scopes` already leads with the workforce aggregate, so no need to prepend
  // it again (doing so double-fetched it and made the report ambiguous).
  const observed = dry ? [] : await Promise.all(scopes.map((s) => s.scope).map(readBack));

  const failedLegs = legs.filter((l) => !l.ok);
  const degradedLegs = legs.filter((l) => l.degraded);
  const report = {
    generated_at: new Date().toISOString(),
    days: Number(DAYS),
    table: TABLE,
    scopes: scopes.map((s) => s.scope),
    legs,
    observed,
    // The three questions the agent's note must answer.
    verdict: {
      failed: failedLegs.map((l) => l.label),
      degraded: degradedLegs.map((l) => l.label),
      stale_repo_scopes: observed
        .filter((o) => o.repo?.freshness?.state === "stale")
        .map((o) => o.scope),
      missing_repo_scopes: observed.filter((o) => o.reachable && !o.repo).map((o) => o.scope),
      lifecycle_last_dates: Object.fromEntries(
        observed.filter((o) => o.reachable).map((o) => [o.scope, o.lifecycle?.last_date ?? null]),
      ),
    },
  };

  writeFileSync(OUT, `${JSON.stringify(report, null, 2)}\n`);
  console.error(
    `refresh.mjs: ${legs.length} leg(s) — ${failedLegs.length} failed, ${degradedLegs.length} degraded; report -> ${OUT}`,
  );

  if (legs.every((l) => !l.ok)) return 3;
  return failedLegs.length > 0 || degradedLegs.length > 0 ? 2 : 0;
}

if (process.argv[1] && import.meta.url === `file://${process.argv[1]}`) {
  process.exit(await main());
}

#!/usr/bin/env node
// podcast-publish / build-rss — standalone feed rebuild (operator escape hatch).
// Triggers the deterministic wf-podcast Lambda's /podcast/rss route, which
// assembles the feed from every audio-ready/published episode (enclosure = the
// public MP3, <description> = show-notes + the mandatory citations, GUID = slug)
// and writes it to the public podcast/feed.xml — WITHOUT flipping any status.
//
// The daily flow doesn't need this (publish.mjs already rebuilds the feed); use
// it to refresh the feed after editing show-notes/citations, or before/after the
// one-time Spotify submission. The operator submits the feed URL to Spotify once;
// subsequent episodes auto-ingest on the next rebuild.
//
// Auth is IAM (SigV4) — the same pattern as synthesize.mjs / publish.mjs. The
// CCR cadence never runs this (Notion-only, no AWS). No new credential type.
//
// Usage:
//   aws-vault exec <profile> -- node workforce/skills/podcast-publish/build-rss.mjs
//
// Env:
//   WF_PODCAST_API_BASE  override the API base (default: prod execute-api URL)
//   AWS_REGION           SigV4 region (default us-west-2)
//
// Exit codes:
//   0  — feed rebuilt (JSON carries the feedUrl + episode count)
//   1  — bad env / missing AWS creds
//   2  — Lambda returned 4xx
//   3  — Lambda 5xx / network error (fail loud — e.g. an uncited episode)

import { spawnSync } from "node:child_process";

const API_BASE = (
  process.env.WF_PODCAST_API_BASE ??
  "https://sjhikazsf9.execute-api.us-west-2.amazonaws.com/prod"
).replace(/\/+$/, "");
const REGION = process.env.AWS_REGION ?? "us-west-2";

const { AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY, AWS_SESSION_TOKEN } = process.env;
if (!AWS_ACCESS_KEY_ID || !AWS_SECRET_ACCESS_KEY) {
  console.error("build-rss.mjs: AWS credentials missing — run under CI OIDC / aws-vault (the route is IAM-authorized)");
  process.exit(1);
}

const args = [
  "-sS",
  "-X", "POST",
  "-H", "content-type: application/json",
  "-w", "\n%{http_code}",
  `${API_BASE}/podcast/rss`,
  "--aws-sigv4", `aws:amz:${REGION}:execute-api`,
  "--user", `${AWS_ACCESS_KEY_ID}:${AWS_SECRET_ACCESS_KEY}`,
];
if (AWS_SESSION_TOKEN) args.push("-H", `x-amz-security-token: ${AWS_SESSION_TOKEN}`);
args.push("--data-binary", "{}");

const res = spawnSync("curl", args, { encoding: "utf8" });
if (res.status !== 0) {
  console.error(`build-rss.mjs: curl failed: ${res.stderr}`);
  process.exit(3);
}
const out = res.stdout;
const nl = out.lastIndexOf("\n");
const status = Number(out.slice(nl + 1));
console.log(out.slice(0, nl));
if (status >= 200 && status < 300) process.exit(0);
if (status >= 400 && status < 500) { console.error(`build-rss.mjs: HTTP ${status}`); process.exit(2); }
console.error(`build-rss.mjs: HTTP ${status} (fail loud)`);
process.exit(3);

#!/usr/bin/env node
// podcast-publish picker — list up to N oldest episodes at a given podcastStatus,
// so the publish cadence can set the voice + show-notes params on each. Mirror of
// the article-level2 picker shape (query the unified DB, filter, oldest-first)
// keyed on the `status`-type podcastStatus property.
//
// Output (stdout, single JSON line): { episodes: [{pageId, slug, title}, …] }
// (empty array ⇒ nothing to do — the skill skips, producing no write).
//
// NOTION_API_KEY from credentials["notion.integration_token"].apiKey. DB id is
// a non-secret constant (overridable by NOTION_DB_ID).
//
// Usage:
//   NOTION_API_KEY=… node pick-episodes.mjs --status approved [--limit 5]
//
// Exit: 0 printed (pick or empty), 1 bad env, 3 Notion/network error.

const NOTION_VERSION = "2022-06-28";
const NOTION_API = "https://api.notion.com/v1";
const UNIFIED_DB_ID = process.env.NOTION_DB_ID || "34fd0f0b-e61e-817a-9f6b-dc65b0d5b4cc";

function arg(name, def) {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 && i + 1 < process.argv.length ? process.argv[i + 1] : def;
}
const apiKey = process.env.NOTION_API_KEY;
const status = (arg("status", "") || "").toLowerCase();
const limit = Number(arg("limit", "5"));
if (!apiKey) { console.error("pick-episodes.mjs: NOTION_API_KEY is required"); process.exit(1); }
if (!status) { console.error("pick-episodes.mjs: --status <podcastStatus> is required"); process.exit(1); }

function propText(prop) {
  if (!prop) return "";
  switch (prop.type) {
    case "title": return (prop.title ?? []).map((t) => t.plain_text).join("");
    case "rich_text": return (prop.rich_text ?? []).map((t) => t.plain_text).join("");
    case "url": return prop.url ?? "";
    case "select": return prop.select?.name ?? "";
    case "status": return prop.status?.name ?? "";
    default: return "";
  }
}
async function queryAll(databaseId) {
  const pages = []; let cursor;
  do {
    const res = await fetch(`${NOTION_API}/databases/${databaseId}/query`, {
      method: "POST",
      headers: { authorization: `Bearer ${apiKey}`, "notion-version": NOTION_VERSION, "content-type": "application/json" },
      body: JSON.stringify(cursor ? { start_cursor: cursor, page_size: 100 } : { page_size: 100 }),
    });
    if (!res.ok) throw new Error(`query ${databaseId} → HTTP ${res.status}: ${(await res.text()).slice(0, 200)}`);
    const data = await res.json();
    pages.push(...(data.results ?? []));
    cursor = data.has_more ? data.next_cursor : undefined;
  } while (cursor);
  return pages;
}
const slugFromId = (id) => String(id).replace(/-/g, "").slice(0, 12);

try {
  const pages = await queryAll(UNIFIED_DB_ID);
  const episodes = pages
    .filter((p) => propText(p.properties?.podcastStatus).toLowerCase() === status)
    .sort((a, b) => (a.created_time ?? "").localeCompare(b.created_time ?? ""))
    .slice(0, Math.max(0, limit))
    .map((p) => ({
      pageId: p.id,
      slug: propText(p.properties?.LegacySlug) || slugFromId(p.id),
      title: propText(p.properties?.Title),
    }));
  console.log(JSON.stringify({ episodes }));
  process.exit(0);
} catch (err) {
  console.error(`pick-episodes.mjs: ${err instanceof Error ? err.message : String(err)}`);
  process.exit(3);
}

#!/usr/bin/env node
// podcast-publish / publish — the audio-ready → published transition. Triggers
// the deterministic wf-podcast Lambda's /podcast/publish route, which flips up
// to 5 oldest `audio-ready` episodes to `published` and rebuilds the RSS feed
// (enclosure = the public MP3, <description> = Celeste's podcastShowNotes + the
// mandatory citations). No judgment here — the show-notes framing is a Notion
// parameter Celeste's cadence sets beforehand; this only executes the transition.
//
// Auth is IAM (SigV4) — run from CI (OIDC) or by the operator, same pattern as
// synthesize.mjs. The CCR cadence never runs this (Notion-only, no AWS). No new
// credential type.
//
// Usage:
//   aws-vault exec <profile> -- node workforce/skills/podcast-publish/publish.mjs
//
// Env: WF_PODCAST_API_BASE (default prod execute-api), AWS_REGION (us-west-2).
//
// Exit codes: 0 published (JSON carries published[] + feedUrl), 1 missing
// creds, 2 Lambda 4xx, 3 Lambda 5xx / network (fail loud).

import { spawnSync } from "node:child_process";

const API_BASE = (
  process.env.WF_PODCAST_API_BASE ??
  "https://sjhikazsf9.execute-api.us-west-2.amazonaws.com/prod"
).replace(/\/+$/, "");
const REGION = process.env.AWS_REGION ?? "us-west-2";

const { AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY, AWS_SESSION_TOKEN } = process.env;
if (!AWS_ACCESS_KEY_ID || !AWS_SECRET_ACCESS_KEY) {
  console.error("publish.mjs: AWS credentials missing — run under CI OIDC / aws-vault (the route is IAM-authorized)");
  process.exit(1);
}

const args = [
  "-sS", "-X", "POST", "-H", "content-type: application/json", "-w", "\n%{http_code}",
  `${API_BASE}/podcast/publish`,
  "--aws-sigv4", `aws:amz:${REGION}:execute-api`,
  "--user", `${AWS_ACCESS_KEY_ID}:${AWS_SECRET_ACCESS_KEY}`,
];
if (AWS_SESSION_TOKEN) args.push("-H", `x-amz-security-token: ${AWS_SESSION_TOKEN}`);
args.push("--data-binary", "{}");

const res = spawnSync("curl", args, { encoding: "utf8" });
if (res.status !== 0) { console.error(`publish.mjs: curl failed: ${res.stderr}`); process.exit(3); }
const out = res.stdout;
const nl = out.lastIndexOf("\n");
const status = Number(out.slice(nl + 1));
console.log(out.slice(0, nl));
if (status >= 200 && status < 300) process.exit(0);
if (status >= 400 && status < 500) { console.error(`publish.mjs: HTTP ${status}`); process.exit(2); }
console.error(`publish.mjs: HTTP ${status} (fail loud)`);
process.exit(3);

#!/usr/bin/env node
// podcast-publish param writer — set the publish-side judgment parameters on one
// `approved` episode in a single Notion PATCH: the narrator voice (Odette's
// casting, folded into Celeste's cadence) and the show-notes framing (Celeste).
// The CI synthesis reads podcastVoice (else random); the CI publish leads the
// feed <description> with podcastShowNotes, then the mandatory citations.
//
// This owns the deterministic Notion write so the LLM can't mangle the page
// schema. At least one of --voice / --notes-file must be given.
//
// NOTION_API_KEY from credentials["notion.integration_token"].apiKey.
//
// Usage:
//   NOTION_API_KEY=… node set-params.mjs --page-id <id> \
//     [--voice <Takumi|Kazuha|Tomoko>] [--notes-file /tmp/notes.txt]
//
// Exit: 0 written, 1 bad args/env/file, 2 voice not in pool / empty notes / auth,
//       3 Notion error.

import { readFileSync } from "node:fs";

const NOTION_VERSION = "2022-06-28";
const NOTION_API = "https://api.notion.com/v1";
// Mirror of JA_NEURAL_VOICES in the wf-podcast Lambda. Casting outside the pool
// is rejected so synthesis never gets an unsupported VoiceId.
const VOICE_POOL = ["Takumi", "Kazuha", "Tomoko"];

function arg(name) {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 && i + 1 < process.argv.length ? process.argv[i + 1] : undefined;
}
const apiKey = process.env.NOTION_API_KEY;
const pageId = arg("page-id");
const voice = arg("voice");
const notesFile = arg("notes-file");

if (!apiKey) { console.error("set-params.mjs: NOTION_API_KEY is required"); process.exit(1); }
if (!pageId) { console.error("set-params.mjs: --page-id is required"); process.exit(1); }
if (!voice && !notesFile) { console.error("set-params.mjs: at least one of --voice / --notes-file is required"); process.exit(1); }

const properties = {};

if (voice !== undefined) {
  if (!VOICE_POOL.includes(voice)) {
    console.error(`set-params.mjs: voice "${voice}" not in the JA Neural pool ${JSON.stringify(VOICE_POOL)} (exit 2)`);
    process.exit(2);
  }
  properties.podcastVoice = { rich_text: [{ type: "text", text: { content: voice } }] };
}

if (notesFile !== undefined) {
  let notes;
  try { notes = readFileSync(notesFile, "utf8").trim(); }
  catch (err) { console.error(`set-params.mjs: cannot read --notes-file: ${err instanceof Error ? err.message : String(err)}`); process.exit(1); }
  if (!notes) { console.error("set-params.mjs: notes are empty — refusing to write blank show-notes (exit 2)"); process.exit(2); }
  // Chunk into ≤2000-char rich_text objects so nothing is silently dropped.
  const chunks = [];
  for (let i = 0; i < notes.length; i += 2000) chunks.push({ type: "text", text: { content: notes.slice(i, i + 2000) } });
  properties.podcastShowNotes = { rich_text: chunks };
}

try {
  const res = await fetch(`${NOTION_API}/pages/${pageId}`, {
    method: "PATCH",
    headers: { authorization: `Bearer ${apiKey}`, "notion-version": NOTION_VERSION, "content-type": "application/json" },
    body: JSON.stringify({ properties }),
  });
  const text = await res.text().catch(() => "");
  if (res.ok) { console.log(`set-params.mjs: page ${pageId} set ${Object.keys(properties).join(" + ")}`); process.exit(0); }
  if (res.status === 401 || res.status === 403) { console.error(`set-params.mjs: auth rejected (HTTP ${res.status})`); process.exit(2); }
  console.error(`set-params.mjs: Notion API error (HTTP ${res.status}): ${text.slice(0, 300)}`);
  process.exit(3);
} catch (err) {
  console.error(`set-params.mjs: fetch failed: ${err instanceof Error ? err.message : String(err)}`);
  process.exit(3);
}

#!/usr/bin/env node
// podcast-publish / synthesize — trigger the deterministic wf-podcast Lambda to
// turn `approved` episodes into MP3s (Epic-017). This script carries NO judgment.
//
// Two-phase, because Amazon Polly synthesis of a full episode takes longer than
// the API Gateway HTTP-API hard 30s integration timeout (a real batch ran ~55s
// → the old single synchronous POST 503'd at 30s even though synthesis
// succeeded). So:
//   1. KICKOFF  — POST {} → the Lambda StartSpeechSynthesisTask's up to 5 oldest
//      `approved` episodes (Polly does the waiting, not the Lambda) and returns
//      202 with the task handles. Fast, well under 30s.
//   2. POLL     — POST {finalize:[handles]} on an interval; the Lambda finalizes
//      each completed Polly task (copy MP3 → public key, write audioUrl +
//      podcastStatus=audio-ready to Notion) and reports {done,pending}. Each
//      poll call is fast too. Loop until done or the poll budget is exhausted.
// The taskId is the only state and it lives in THIS caller — no per-Lambda
// nested invocation (R-N1).
//
// Auth is IAM (the CI OIDC role / the operator's AWS credentials sign each
// request) — NOT the CCR cadence, which is Notion-only and never touches AWS.
// The Notion token lives in the Lambda (its IAM role), never in this session.
//
// Usage:
//   aws-vault exec <profile> -- node workforce/skills/podcast-publish/synthesize.mjs            # oldest approved (≤5)
//   aws-vault exec <profile> -- node workforce/skills/podcast-publish/synthesize.mjs --slug c91368439868
//
// Env:
//   WF_PODCAST_API_BASE   override the API base (default: prod execute-api URL)
//   AWS_REGION            SigV4 region (default us-west-2)
//   PODCAST_POLL_BUDGET_MS  total poll budget (default 840000 = 14 min, under the
//                           20 min CI job timeout)
//   PODCAST_POLL_INTERVAL_MS  poll interval (default 8000 = 8s)
//
// Exit codes:
//   0  — synthesised (or a skip: no approved episode) — read the JSON
//   1  — bad env / missing AWS creds
//   2  — Lambda returned 4xx (bad request / auth)
//   3  — Lambda 5xx / network / a Polly failure, or the poll budget expired with
//        episodes still un-synthesised (fail loud — C-4)

import { spawnSync } from "node:child_process";

const API_BASE = (
  process.env.WF_PODCAST_API_BASE ??
  "https://sjhikazsf9.execute-api.us-west-2.amazonaws.com/prod"
).replace(/\/+$/, "");
const REGION = process.env.AWS_REGION ?? "us-west-2";
const POLL_BUDGET_MS = Number(process.env.PODCAST_POLL_BUDGET_MS ?? "840000");
const POLL_INTERVAL_MS = Number(process.env.PODCAST_POLL_INTERVAL_MS ?? "8000");

function arg(name) {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 && i + 1 < process.argv.length ? process.argv[i + 1] : undefined;
}
const slug = arg("slug");

const { AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY, AWS_SESSION_TOKEN } = process.env;
if (!AWS_ACCESS_KEY_ID || !AWS_SECRET_ACCESS_KEY) {
  console.error("synthesize.mjs: AWS credentials missing — run under CI OIDC or `aws-vault exec <profile> --` (the route is IAM-authorized)");
  process.exit(1);
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// One SigV4-signed POST to /podcast/synthesize. Returns {status, text, json}.
function post(payload) {
  const body = JSON.stringify(payload);
  const args = [
    "-sS",
    "-X", "POST",
    "-H", "content-type: application/json",
    "-w", "\n%{http_code}",
    `${API_BASE}/podcast/synthesize`,
    "--aws-sigv4", `aws:amz:${REGION}:execute-api`,
    "--user", `${AWS_ACCESS_KEY_ID}:${AWS_SECRET_ACCESS_KEY}`,
  ];
  if (AWS_SESSION_TOKEN) args.push("-H", `x-amz-security-token: ${AWS_SESSION_TOKEN}`);
  args.push("--data-binary", body);

  const res = spawnSync("curl", args, { encoding: "utf8" });
  if (res.status !== 0) {
    return { status: 0, text: `curl failed: ${res.stderr}`, json: undefined };
  }
  const out = res.stdout;
  const nl = out.lastIndexOf("\n");
  const status = Number(out.slice(nl + 1));
  const text = out.slice(0, nl);
  let parsed;
  try { parsed = JSON.parse(text); } catch { /* non-JSON error body */ }
  return { status, text, json: parsed };
}

// Map a non-2xx response to the documented exit code (fail loud on 5xx).
function bail(label, res) {
  if (res.status >= 400 && res.status < 500) { console.error(`synthesize.mjs: ${label} HTTP ${res.status}: ${res.text}`); process.exit(2); }
  console.error(`synthesize.mjs: ${label} HTTP ${res.status} (fail loud): ${res.text}`);
  process.exit(3);
}

// ── 1. Kickoff ────────────────────────────────────────────────────────────────
const kicked = post(slug ? { slug } : {});
if (kicked.status === 200 && kicked.json?.skip) {
  console.log(kicked.text); // {skip:true,…}
  process.exit(0);
}
if (kicked.status !== 202) bail("kickoff", kicked);

const handles = Array.isArray(kicked.json?.started) ? kicked.json.started : [];
if (handles.length === 0) {
  console.error("synthesize.mjs: kickoff returned 202 with no handles");
  process.exit(3);
}
console.error(`synthesize.mjs: started ${handles.length} Polly task(s); polling for completion (budget ${Math.round(POLL_BUDGET_MS / 1000)}s)…`);

// ── 2. Poll until every started task is finalized → audio-ready ─────────────────
let pending = handles;
const deadline = Date.now() + POLL_BUDGET_MS;
while (pending.length > 0) {
  if (Date.now() > deadline) {
    console.error(`synthesize.mjs: poll budget expired with ${pending.length} episode(s) still un-synthesised (fail loud)`);
    process.exit(3);
  }
  await sleep(POLL_INTERVAL_MS);
  const res = post({ finalize: pending });
  if (res.status !== 200) bail("finalize", res); // a Polly failure throws → 5xx → exit 3
  const results = Array.isArray(res.json?.results) ? res.json.results : [];
  const doneIds = new Set(results.filter((r) => r.done).map((r) => r.pageId));
  pending = pending.filter((h) => !doneIds.has(h.pageId));
  console.error(`  audio-ready ${handles.length - pending.length}/${handles.length}`);
}

console.log(JSON.stringify({ synthesized: handles.length, slugs: handles.map((h) => h.slug) }));
process.exit(0);

#!/usr/bin/env node
// podcast-publish / trigger-pipeline — fire the `podcast-pipeline.yml` workflow
// (synthesize + publish) via GitHub `workflow_dispatch`, so the publish cadence
// can hand off to the deterministic pipeline in ONE continuous flow instead of
// waiting for the daily cron. This is the optional last leg after the judgment
// half (podcastVoice + podcastShowNotes) has been set on the approved episodes.
//
// GitHub-only — the AWS trust boundary stays closed (R-N1 / ADR-0016). This
// script dispatches the existing CI workflow; that workflow then does all the
// Polly/S3/RSS work via its OWN OIDC→AWS role. The cadence never touches AWS;
// it only asks GitHub to run the workflow.
//
// Auth: the project-scoped github.token (credentials['github.token'].token),
// exported as GITHUB_TOKEN. It MUST carry the `workflow` scope (classic PAT) or
// `Actions: write` (fine-grained) — without it GitHub returns 403
// ("not accessible by integration").
//
// CAVEAT (read before debugging a 403): a Claude Code session's egress proxy
// injects a FIXED session GitHub identity for api.github.com and ignores both
// this token and GITHUB_TOKEN, so this script cannot be smoke-tested from such
// a session (it 403s as the session identity). It works where the PAT is
// actually used: the CCR cadence runner, GitHub Actions/CI, or an operator
// shell.
//
// Usage:
//   GITHUB_TOKEN=<…> node trigger-pipeline.mjs [--ref main] [--workflow podcast-pipeline.yml]
//
// Exit codes:
//   0  — dispatched (HTTP 204) — read the JSON
//   1  — missing GITHUB_TOKEN
//   2  — GitHub 4xx (e.g. 403: token lacks the workflow/Actions:write scope)
//   3  — GitHub 5xx / network error (fail loud)

import { spawnSync } from "node:child_process";

const OWNER = process.env.WF_PODCAST_REPO_OWNER ?? "refluster";
const REPO = process.env.WF_PODCAST_REPO_NAME ?? "ai-native-article";

function arg(name, def) {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 && i + 1 < process.argv.length ? process.argv[i + 1] : def;
}
const ref = arg("ref", "main");
const workflow = arg("workflow", "podcast-pipeline.yml");

const token = process.env.GITHUB_TOKEN;
if (!token) {
  console.error("trigger-pipeline.mjs: GITHUB_TOKEN is required (credentials['github.token'].token; needs the `workflow` scope / Actions:write)");
  process.exit(1);
}

const url = `https://api.github.com/repos/${OWNER}/${REPO}/actions/workflows/${workflow}/dispatches`;
const res = spawnSync("curl", [
  "-sS", "-o", "/dev/null", "-w", "%{http_code}",
  "-X", "POST",
  "-H", `Authorization: Bearer ${token}`,
  "-H", "Accept: application/vnd.github+json",
  "-H", "X-GitHub-Api-Version: 2022-11-28",
  url,
  "-d", JSON.stringify({ ref }),
], { encoding: "utf8" });

if (res.status !== 0) {
  console.error(`trigger-pipeline.mjs: curl failed: ${res.stderr}`);
  process.exit(3);
}
const code = Number(res.stdout.trim());
if (code === 204) {
  console.log(JSON.stringify({ dispatched: true, workflow, ref }));
  process.exit(0);
}
if (code >= 400 && code < 500) {
  console.error(`trigger-pipeline.mjs: HTTP ${code} — the token likely lacks the \`workflow\` scope / Actions:write (or a session proxy is overriding auth)`);
  process.exit(2);
}
console.error(`trigger-pipeline.mjs: HTTP ${code} (fail loud)`);
process.exit(3);

#!/usr/bin/env node
// podcast-script picker — choose ONE analysis (L3/L4) article that has no
// podcast yet, oldest first, so the Cadence turns the back-catalogue into
// episodes deterministically. Mirror of article-level2/pick-l1-source.mjs in
// shape (query the unified Articles DB, apply the coverage filter, oldest-first,
// emit JSON or a skip), but the "coverage" key here is the article's own
// `podcastStatus` property rather than a separate covered-URL set.
//
// Eligibility (all must hold):
//   - Type == "analysis"                          (the L3/L4 synthesis articles)
//   - Status ∈ {ready, published}                  ("live" = what the site serves.
//                                                   fetch-notion.mjs exports every
//                                                   row with NO Status filter, and
//                                                   the post-GAS cadences write
//                                                   Status=ready with nothing left
//                                                   to flip it to published — that
//                                                   value survives only on legacy
//                                                   migrated rows. Requiring
//                                                   "published" alone starved this
//                                                   picker of every cadence-authored
//                                                   article. draft/archived stay out.)
//   - podcastStatus is empty or "none"             (no podcast exists yet)
//   - SourceURLs is non-empty                      (citable — an article with no
//                                                   sources can't produce a
//                                                   compliant episode and would
//                                                   block the oldest-first queue)
//
// Output (stdout, single JSON line):
//   { pageId, slug, title, sourceUrls, date }      — the chosen article, or
//   { skip: true, reason }                          — nothing eligible this fire
//
// The chosen article's BODY is not returned here (it can be large); the SKILL
// instructs the agent to ground the script in the published article markdown
// (kohuehara.xyz) and the cited sources. `sourceUrls` is the citation seed.
//
// NOTION_API_KEY comes from the task's injected
// credentials["notion.integration_token"].apiKey. The unified DB id is a
// non-secret constant (already committed in article-level2 + the pipeline),
// overridable by NOTION_DB_ID for tests.
//
// Exit codes:
//   0  — printed a pick OR a skip (both are success; read the JSON)
//   1  — bad env (no API key)
//   3  — Notion API / network error

const NOTION_VERSION = "2022-06-28";
const NOTION_API = "https://api.notion.com/v1";
const UNIFIED_DB_ID = process.env.NOTION_DB_ID || "34fd0f0b-e61e-817a-9f6b-dc65b0d5b4cc";

const apiKey = process.env.NOTION_API_KEY;
if (!apiKey) {
  console.error("pick-article.mjs: NOTION_API_KEY is required (credentials['notion.integration_token'].apiKey)");
  process.exit(1);
}

function propText(prop) {
  if (!prop) return "";
  switch (prop.type) {
    case "title": return (prop.title ?? []).map((t) => t.plain_text).join("");
    case "rich_text": return (prop.rich_text ?? []).map((t) => t.plain_text).join("");
    case "date": return prop.date?.start ?? "";
    case "url": return prop.url ?? "";
    case "select": return prop.select?.name ?? "";
    case "status": return prop.status?.name ?? "";
    case "multi_select": return (prop.multi_select ?? []).map((o) => o.name).join(", ");
    default: return "";
  }
}

async function queryAll(databaseId) {
  const pages = [];
  let cursor;
  do {
    const res = await fetch(`${NOTION_API}/databases/${databaseId}/query`, {
      method: "POST",
      headers: {
        authorization: `Bearer ${apiKey}`,
        "notion-version": NOTION_VERSION,
        "content-type": "application/json",
      },
      body: JSON.stringify(cursor ? { start_cursor: cursor, page_size: 100 } : { page_size: 100 }),
    });
    if (!res.ok) {
      const body = await res.text().catch(() => "");
      throw new Error(`query ${databaseId} → HTTP ${res.status}: ${body.slice(0, 300)}`);
    }
    const data = await res.json();
    pages.push(...(data.results ?? []));
    cursor = data.has_more ? data.next_cursor : undefined;
  } while (cursor);
  return pages;
}

function slugFromId(id) {
  return String(id).replace(/-/g, "").slice(0, 12);
}

try {
  const pages = await queryAll(UNIFIED_DB_ID);

  const sourceUrlsOf = (props) =>
    (propText(props.SourceURLs) ||
      propText(props["Source Article URLs"]) ||
      propText(props["Source URLs"])).trim();

  // Base eligibility: a live (site-visible) Type=analysis article with no
  // podcast yet. "Live" = Status ready OR published — see the header note:
  // the site publishes every row regardless of Status, the cadences write
  // `ready`, and nothing flips ready→published since the GAS L4 batch retired
  // (2026-06-28). draft/archived (and any unknown value) remain excluded.
  const LIVE_STATUSES = new Set(["ready", "published"]);
  const base = pages.filter((p) => {
    const props = p.properties ?? {};
    if (propText(props.Type) !== "analysis") return false;
    if (!LIVE_STATUSES.has(propText(props.Status).trim().toLowerCase())) return false;
    const podStatus = propText(props.podcastStatus).trim().toLowerCase();
    if (podStatus && podStatus !== "none") return false; // already has a podcast in flight/done
    return true;
  });

  // Citable-only: an article with NO SourceURLs cannot become a compliant
  // episode — the script needs a non-empty citation list (C-1; publish-notion
  // exit-2s on empty citations). Being oldest-first, an uncitable article would
  // otherwise permanently block the picker (the whole queue stalls on one
  // un-podcastable row). Skip it so the picker advances to the next citable
  // article. To podcast such an article, add its SourceURLs in Notion.
  const eligible = base
    .filter((p) => sourceUrlsOf(p.properties ?? {}))
    .sort((a, b) => (a.created_time ?? "").localeCompare(b.created_time ?? ""));

  // Observability (no silent caps — governance-mechanisms.md): surface HOW MANY
  // eligible-but-uncitable rows were skipped, so the perpetually-un-podcast
  // backlog is visible on stderr rather than growing silently.
  const uncitableSkipped = base.length - eligible.length;
  if (uncitableSkipped > 0) {
    console.error(`pick-article.mjs: skipped ${uncitableSkipped} uncitable analysis article(s) with empty SourceURLs — add SourceURLs in Notion to podcast them`);
  }

  if (eligible.length === 0) {
    console.log(JSON.stringify({ skip: true, reason: "no live (ready/published) analysis article with SourceURLs and without a podcast" }));
    process.exit(0);
  }

  const page = eligible[0];
  const props = page.properties ?? {};
  const legacySlug = propText(props.LegacySlug);
  const slug = legacySlug || slugFromId(page.id);
  const out = {
    pageId: page.id,
    slug,
    title: propText(props.Title),
    sourceUrls:
      propText(props.SourceURLs) ||
      propText(props["Source Article URLs"]) ||
      propText(props["Source URLs"]),
    date: propText(props.Date) || (page.created_time ?? "").slice(0, 10),
  };
  console.log(JSON.stringify(out));
  process.exit(0);
} catch (err) {
  console.error(`pick-article.mjs: ${err instanceof Error ? err.message : String(err)}`);
  process.exit(3);
}

#!/usr/bin/env node
// Deterministic podcast-script writer — invoked by the CCR agent-runner after
// it has *generated* the narration script + the source citations. The LLM owns
// the judgment (the spoken-word script, the citation list); this script owns
// the structurally-exact Notion write so the failure class "LLM hand-edits the
// page JSON and guesses the schema wrong" cannot recur. Same shape as
// article-level2/publish-notion.mjs, with two differences:
//
//   1. It UPDATES an existing article page (PATCH /pages/{page_id}) rather than
//      creating one — the script attaches to the article it adapts (C-2: the
//      article's Notion page stays the source of truth).
//   2. It adds a CITATION GUARD: an empty/whitespace --citations-file is the
//      mechanical implementation of the team's mandatory-citation policy
//      (Idris / ADR-0016) — exit 2, never publish an uncited derivative.
//
// Properties written (Story 4 schema — operator pre-creates them):
//   podcastScript  (rich_text)  ← the narration script, chunked ≤2000-char/item
//   podcastSources (rich_text)  ← the source citations (mandatory, non-empty)
//   podcastStatus  (select)     ← "script-ready"
//
// W-1 (editorial integrity): refuses an empty/too-short script, an LLM-failure
// prelude, or a script whose last line looks cut off mid-content (the canonical
// scripts/lib/truncation.mjs heuristic) — failing loud (exit 2) rather than
// attaching a degraded script. The audio step (Story 5) only picks up
// script-ready pages, so the guard must fire here, per-episode.
//
// NOTION_API_KEY comes from the task's injected
// credentials["notion.integration_token"].apiKey.
//
// Usage:
//   NOTION_API_KEY="<apiKey>" \
//     node workforce/skills/podcast-script/publish-notion.mjs \
//       --page-id <article notion page id, from pick-article.mjs> \
//       --script-file /tmp/script.md \
//       --citations-file /tmp/citations.txt \
//       [--status script-ready]
//
// Exit codes:
//   0  — page updated (podcastStatus=script-ready)
//   1  — bad args / env / file unreadable
//   2  — W-1 editorial guard failed (empty/short/truncated script, artefact
//        prelude) OR empty citations (citation guard) OR 401/403 auth
//   3  — Notion API error / network error

import { readFileSync } from "node:fs";
import { isTruncatedMarkdown, lastNonEmptyLine } from "../../../scripts/lib/truncation.mjs";

const NOTION_VERSION = "2022-06-28";
const NOTION_API = "https://api.notion.com/v1";
// A ~10-minute single-narrator script is several thousand chars; anything
// shorter than this floor is almost certainly truncated/empty (C-1).
const MIN_SCRIPT_CHARS = 600;
const ARTEFACT_PRELUDE =
  /^\s*(as an ai|here is|here's|i apologize|i'm sorry|certainly!|sure,|of course)/i;

function arg(name) {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 && i + 1 < process.argv.length ? process.argv[i + 1] : undefined;
}

const apiKey = process.env.NOTION_API_KEY;
const pageId = arg("page-id");
const scriptFile = arg("script-file");
const citationsFile = arg("citations-file");
const complianceFile = arg("compliance-file"); // optional: Idris's compliance verdict
const status = arg("status") ?? "script-ready";

const VALID_STATUS = new Set(["none", "script-ready", "approved", "audio-ready", "published"]);

if (!apiKey) { console.error("publish-notion.mjs: NOTION_API_KEY env var is required (from credentials['notion.integration_token'].apiKey)"); process.exit(1); }
if (!pageId) { console.error("publish-notion.mjs: --page-id <notion page id> is required (from pick-article.mjs)"); process.exit(1); }
if (!scriptFile) { console.error("publish-notion.mjs: --script-file <path> is required"); process.exit(1); }
if (!citationsFile) { console.error("publish-notion.mjs: --citations-file <path> is required"); process.exit(1); }
if (!VALID_STATUS.has(status)) {
  console.error(`publish-notion.mjs: --status must be one of ${[...VALID_STATUS].join("|")} (got "${status}")`);
  process.exit(1);
}

function readFileOrDie(path, label) {
  try {
    return readFileSync(path, "utf8");
  } catch (err) {
    console.error(`publish-notion.mjs: cannot read ${label} "${path}": ${err instanceof Error ? err.message : String(err)}`);
    process.exit(1);
  }
}

const script = readFileOrDie(scriptFile, "--script-file");
const citations = readFileOrDie(citationsFile, "--citations-file");

// ── Citation guard (mandatory-citation policy — Idris / ADR-0016) ───────────
// An empty or whitespace-only citations file is a hard fail: a podcast derived
// from third-party news must carry its sources, mechanically, every episode.
if (citations.trim().length === 0) {
  console.error("publish-notion.mjs: --citations-file is empty — refusing to attach an uncited podcast script (mandatory-citation guard, ADR-0016). exit 2");
  process.exit(2);
}

// ── W-1 editorial guards on the script (fail loud, do not attach) ───────────
const trimmed = script.trim();
if (trimmed.length < MIN_SCRIPT_CHARS) {
  console.error(`publish-notion.mjs: script is ${trimmed.length} chars (< ${MIN_SCRIPT_CHARS}) — refusing to attach a truncated/empty script (W-1)`);
  process.exit(2);
}
if (ARTEFACT_PRELUDE.test(trimmed.slice(0, 50))) {
  console.error("publish-notion.mjs: script opens with an LLM-failure prelude — refusing to attach (W-1)");
  process.exit(2);
}
if (isTruncatedMarkdown(trimmed)) {
  console.error(`publish-notion.mjs: script looks cut off mid-content (last line: "${lastNonEmptyLine(trimmed)}") — refusing to attach a truncated script (W-1)`);
  process.exit(2);
}

// Notion rich_text: each text object's content is capped at 2000 chars. A long
// script is chunked across multiple objects in the same property so NOTHING is
// dropped (silent truncation would be the exact C-1 failure we guard against).
function richTextChunks(str) {
  const MAX = 2000;
  const out = [];
  for (let i = 0; i < str.length; i += MAX) {
    out.push({ type: "text", text: { content: str.slice(i, i + MAX) } });
  }
  // Notion caps a property's rich_text array at 100 objects (200k chars) — far
  // beyond any plausible script; assert rather than silently drop.
  if (out.length > 100) {
    console.error(`publish-notion.mjs: ${str.length} chars exceeds the 100×2000 Notion rich_text property limit — split the episode (W-1, fail loud)`);
    process.exit(2);
  }
  return out;
}

const properties = {
  podcastScript: { rich_text: richTextChunks(trimmed) },
  podcastSources: { rich_text: richTextChunks(citations.trim()) },
  // podcastStatus is a Notion `status`-type property (operator-created), not a
  // select — write the status shape.
  podcastStatus: { status: { name: status } },
};

// Idris's compliance verdict (optional) — no-verbatim-reproduction +
// citation-completeness check the operator reads before approving. Written to
// the `complianceVerdict` text property alongside the script.
if (complianceFile) {
  let verdict = "";
  try { verdict = readFileSync(complianceFile, "utf8").trim(); }
  catch (err) { console.error(`publish-notion.mjs: cannot read --compliance-file "${complianceFile}": ${err instanceof Error ? err.message : String(err)}`); process.exit(1); }
  if (verdict) properties.complianceVerdict = { rich_text: richTextChunks(verdict) };
}

try {
  const res = await fetch(`${NOTION_API}/pages/${pageId}`, {
    method: "PATCH",
    headers: {
      authorization: `Bearer ${apiKey}`,
      "notion-version": NOTION_VERSION,
      "content-type": "application/json",
    },
    body: JSON.stringify({ properties }),
  });
  const text = await res.text().catch(() => "");
  if (res.ok) {
    console.log(`publish-notion.mjs: updated page ${pageId} — podcastStatus=${status}, script ${trimmed.length} chars, citations ${citations.trim().length} chars`);
    process.exit(0);
  }
  if (res.status === 401 || res.status === 403) {
    console.error(`publish-notion.mjs: auth rejected (HTTP ${res.status}) — project credential bag misconfigured: ${text.slice(0, 400)}`);
    process.exit(2);
  }
  console.error(`publish-notion.mjs: Notion API error (HTTP ${res.status}): ${text.slice(0, 400)}`);
  process.exit(3);
} catch (err) {
  console.error(`publish-notion.mjs: fetch failed: ${err instanceof Error ? err.message : String(err)}`);
  process.exit(3);
}

