// Locks Epic-019 Story 1: a hand-off to a human ALWAYS carries WHY. resolveReasons
// is the mechanical half — an escalating post with no reason, an unknown code,
// or a bare `other` never reaches GitHub (C-4, exit 1 in main()).
describe("resolveReasons — escalation always carries a reason (Epic-019)", () => {
  it("an escalating post with no reason at all throws", () => {
    expect(() => resolveReasons({ body: `verdict\n${NEEDS_HUMAN_MARKER}`, escalating: true })).toThrow(
      /must carry an escalation reason/,
    );
  });

  it("--reason supplies the code: label + marker to append", () => {
    const r = resolveReasons({ body: "verdict", escalating: true, reason: "cannot-seat-panel" });
    expect(r.labels).toEqual(["autopilot:reason:cannot-seat-panel"]);
    expect(r.appendMarker).toBe("<!-- autopilot:reason:cannot-seat-panel -->");
  });

  it("a marker already embedded in the body satisfies the requirement (nothing appended)", () => {
    const body = `verdict\n${NEEDS_HUMAN_MARKER}\n<!-- autopilot:reason:no-reviewer-consensus -->`;
    const r = resolveReasons({ body, escalating: true });
    expect(r.labels).toEqual(["autopilot:reason:no-reviewer-consensus"]);
    expect(r.appendMarker).toBeNull();
  });

  it("--reason matching an embedded marker is not appended twice", () => {
    const body = "verdict\n<!-- autopilot:reason:l0l1-path -->";
    const r = resolveReasons({ body, escalating: true, reason: "l0l1-path" });
    expect(r.labels).toEqual(["autopilot:reason:l0l1-path"]);
    expect(r.appendMarker).toBeNull();
  });

  it("an unknown code throws (C-4), flag or marker alike", () => {
    expect(() => resolveReasons({ body: "v", escalating: true, reason: "sloppy-review" })).toThrow(/unknown/);
    expect(() => resolveReasons({ body: "<!-- autopilot:reason:sloppy-review -->", escalating: true })).toThrow(/unknown/);
  });

  it("`other` requires free text", () => {
    expect(() => resolveReasons({ body: "v", escalating: true, reason: "other" })).toThrow(/free text/);
    const r = resolveReasons({ body: "v", escalating: true, reason: "other", reasonText: "repo archived" });
    expect(r.labels).toEqual(["autopilot:reason:other"]);
    expect(r.appendMarker).toBe("<!-- autopilot:reason:other repo archived -->");
  });

  it("a non-escalating routing comment needs no reason", () => {
    expect(resolveReasons({ body: "**Nadia — cycle 1.**", escalating: false })).toEqual({
      codes: [],
      labels: [],
      appendMarker: null,
    });
  });
});

// Locks the operator directive (2026-07-04, ML-012): persona slugs are not
// GitHub accounts — a raw `@<slug>` in a posted body notifies the real,
// unrelated GitHub user who owns that name (`@yuki` pinged github.com/yuki).
// findRawMentions is the mechanical half: the script refuses (exit 1) any
// body where it finds a mention. Agents are referenced as `wf:<slug>` in
// backticks, which must never trip the guard.
describe("findRawMentions — no raw GitHub @-mentions leave the workforce", () => {
  it("flags the incident shape: a routing comment @-mentioning a persona", () => {
    expect(findRawMentions("- **@yuki** — owns the console surface")).toEqual(["@yuki"]);
  });

  it("flags a skip-line mention and de-dupes repeats", () => {
    const body = "Skipping @maya — no surface. Also skipping @maya.\n@dario is seated.";
    expect(findRawMentions(body).sort()).toEqual(["@dario", "@maya"]);
  });

  it("the canonical wf:<slug> reference in backticks is clean", () => {
    const body = "Reviewers nominated (≥ 3):\n\n- **`wf:yuki`** — console surface\n\nSkipping `wf:maya` — no surface.";
    expect(findRawMentions(body)).toEqual([]);
  });

  it("ignores @-tokens inside inline code spans and fenced blocks", () => {
    const body = "Uses `@anthropic-ai/sdk`.\n\n```ts\n@Injectable()\nclass A {}\n// cc @yuki\n```\n";
    expect(findRawMentions(body)).toEqual([]);
  });

  it("ignores double-backtick spans", () => {
    expect(findRawMentions("quote ``@yuki`` verbatim")).toEqual([]);
  });

  it("flags a mention GitHub would linkify even when bolded or hyphenated", () => {
    expect(findRawMentions("ping **@anthropic-ai** please")).toEqual(["@anthropic-ai"]);
  });

  it("does not flag emails (GitHub does not linkify them either)", () => {
    expect(findRawMentions("contact refluster@gmail.com about it")).toEqual([]);
  });

  it("flags a mention at the very start of the body", () => {
    expect(findRawMentions("@yuki take a look")).toEqual(["@yuki"]);
  });

  it("empty / markerless bodies are clean", () => {
    expect(findRawMentions("")).toEqual([]);
    expect(findRawMentions(`verdict\n\n${NEEDS_HUMAN_MARKER}\n`)).toEqual([]);
  });
});

#!/usr/bin/env node
// Deterministic pr-autopilot POST script — posts ONE routing/verdict comment to
// a PR's issue-comment thread, and (optionally) stamps escalation labels on the
// PR so a human can find the hand-off queue.
//
// R-N9 / W-5 by construction: it writes ONLY an issue comment
// (`POST /repos/{owner}/{repo}/issues/{n}/comments`) and, with --label, issue
// labels (`POST /repos/{owner}/{repo}/issues/{n}/labels`). There is no code path
// that approves, requests-changes, merges, pushes a branch, or opens a PR.
// The external git surface stays comment+label only — agents never gate merges.
//
// The repo (owner/repo) is read from the in-repo project.json; the
// github.token is injected per-fire via the (project × agent × skill)
// binding's project linkage and read here from GITHUB_TOKEN. The comment
// body is read from a FILE so multi-line / Unicode prose can't be mangled
// by shell quoting.
//
// Usage:
//   GITHUB_TOKEN=<credentials['github.token'].token> \
//     node workforce/skills/pr-autopilot/pr-autopilot-post.mjs \
//       --project asp-cloud --pr 42 --body-file /tmp/route-body-42.md \
//       [--needs-human] [--label <name>]   # see escalation rule below
//       [--reason <code> [--reason-text "…"]]   # see reason rule below
//
// ESCALATION ALWAYS CARRIES THE LABEL (operator directive 2026-06-21). Any
// comment that hands a PR to a human — a 🟢 PR touching the target's governance
// L0/L1, a 🔴 verdict, a non-consensus PR, a no-delegation hand-off — MUST be
// stamped `autopilot:needs-human` so the operator finds the queue with
// `is:open label:autopilot:needs-human`. This script applies that label from
// EITHER signal, so a hand-off can never reach a human un-labelled even if one
// is forgotten:
//   - `--needs-human` flag, OR
//   - the hidden marker `<!-- autopilot:needs-human -->` embedded in the verdict
//     body (the SKILL.md escalation template carries it).
// The canonical label name is single-sourced from pr-merge.mjs (ESCALATION_LABEL),
// the same constant the engine stamps on escalation issues — one queue, one name.
//
// REVIEWED (merge-ready) hand-offs (operator directive 2026-06-23). When the
// hand-off is a 🟢 unanimous-green PR held back only by a human gate (the
// target's L0/L1 boundary, or a missing R-N10 delegation), it ALSO carries
// `autopilot:reviewed` — so the operator can tell "reviewed + merge-ready, my
// final call" apart from a 🔴 / cycle-capped / non-consensus escalation that
// still needs work. Stamped from EITHER `--reviewed` OR the hidden body marker
// `<!-- autopilot:reviewed -->`. A 🔴 / non-consensus escalation gets only
// `autopilot:needs-human`, never this.
//
// ESCALATION ALWAYS CARRIES A REASON (Epic-019 Story 1). Any comment that
// hands a PR to a human must also record WHY, from EITHER `--reason <code>`
// (appended to the body as the hidden `<!-- autopilot:reason:<code> -->`
// marker when absent) OR a reason marker already embedded in the body. The
// code becomes an `autopilot:reason:<code>` label — the funnel's aggregation
// source. Fail loud (C-4): an escalating post with NO reason, an unknown
// code, or `other` without free text (`--reason-text`) exits 1. Codes:
// workforce/docs/pr-escalation-reasons.md (v1; single-sourced from
// escalation-reasons.mjs). Additionally, every escalation computes the
// verdict-time L0/L1 check (same fail-closed source as the merge engine) and
// stamps `autopilot:reason:l0l1-path` when the PR touches the target's
// declared L0/L1 set — so the funnel's eligible (non-L0/L1) share is
// derivable for every escalated PR, not just the merge leg.
//
// FLAKY-CHECK AUTO-RERUN (Epic-019 Story 2c). A `checks-failing` escalation
// first attempts ONE bounded rerun via flaky-rerun.mjs: iff every failing
// check is on the evidenced, unexpired allowlist (flaky-checks.json) and the
// PR has never been rerun, the rerun is triggered (with its own audit
// comment + `autopilot:reran` label) and THIS escalation is deferred (exit 0,
// nothing posted) — the next tick re-verdicts. Any other state escalates
// normally. See the Step 5 note in SKILL.md.
//
// Extra `--label <name>` values (repeatable) are merged in. Routing comments
// (cycle 1) carry neither flag nor marker, so they stay unlabelled. Missing
// labels are auto-created (each with its own colour/description).
//
// NO RAW @-MENTIONS (ML-012, operator report 2026-07-04). Persona slugs are
// not GitHub accounts; a raw `@<slug>` in a posted body notifies the real
// GitHub user who owns that name (`@yuki` pinged github.com/yuki). Agents are
// referenced as `wf:<slug>` in backticks; this script fails loud (exit 1) on
// any body carrying a raw @-mention outside backticks/code fences.
//
// Exit codes:
//   0  — comment created (HTTP 201); labels best-effort
//   1  — bad args / project.json missing / body-file unreadable
//   2  — endpoint rejected (auth/4xx)
//   3  — network / unexpected error

import { readFileSync } from "node:fs";
import { fileURLToPath, pathToFileURL } from "node:url";
import { dirname, join } from "node:path";
import { projectRepo } from "./pr-autopilot-scan.mjs";
import { ESCALATION_LABEL, REVIEWED_LABEL, makeGh, prTouchesL0L1 } from "./pr-merge.mjs";
import {
  REASON_LABEL_PREFIX,
  assertReasonCode,
  findReasonMarkers,
  reasonLabel,
  reasonMarker,
} from "./escalation-reasons.mjs";
import { attemptFlakyRerun } from "./flaky-rerun.mjs";

const GH_API = "https://api.github.com";
const HERE = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = join(HERE, "..", "..", "..");

/** Per-label colour + description used when auto-creating a label the target
 *  repo lacks. Unknown labels (explicit --label values) fall back to the
 *  escalation colour. Single object so the two canonical labels never drift. */
const LABEL_META = {
  [ESCALATION_LABEL]: {
    color: "b60205", // red — "an autopilot decision needs a human"
    description: "Autopilot handed this off — a human's call (merge / governance L0/L1 / blocked).",
  },
  [REVIEWED_LABEL]: {
    color: "0e8a16", // green — "reviewed to 🟢 consensus, merge-ready"
    description: "Autopilot reviewed this to a 🟢 unanimous-green consensus; merge-ready, held only by a human gate (L0/L1 / delegation) — the operator merges.",
  },
};
const FALLBACK_LABEL_META = LABEL_META[ESCALATION_LABEL];

/** Meta for the Epic-019 `autopilot:reason:*` family (one label per taxonomy
 *  code, so an exact-name map can't cover them). */
const REASON_LABEL_META = {
  color: "c5def5", // light blue — telemetry, not a work queue
  description: "Epic-019 escalation-reason telemetry — why autopilot handed this PR to a human (wiring, not reviewer performance).",
};

/** Hidden marker the SKILL.md hand-off/escalation verdict template embeds. Its
 *  presence in the comment body forces ESCALATION_LABEL even if --needs-human
 *  was omitted — the mechanical half of "escalation ALWAYS carries the label". */
export const NEEDS_HUMAN_MARKER = "<!-- autopilot:needs-human -->";

/** Hidden marker for a 🟢 merge-ready hand-off. Its presence (or --reviewed)
 *  adds REVIEWED_LABEL alongside ESCALATION_LABEL — the mechanical half of
 *  "a green, human-gated PR is flagged reviewed even if the flag is dropped". */
export const REVIEWED_MARKER = "<!-- autopilot:reviewed -->";

/** Raw GitHub @-mentions found in a comment body's prose (ML-012).
 *
 *  Workforce persona slugs are NOT GitHub accounts: a raw `@<slug>` in a
 *  posted comment notifies whichever real GitHub user owns that name (a
 *  routing comment's `@yuki` pinged the unrelated github.com/yuki,
 *  2026-07-04). Agents are referenced as `wf:<slug>` in backticks; any
 *  literal `@…` token (scoped npm package, decorator) must be quoted in
 *  backticks/code fences, where GitHub never linkifies.
 *
 *  Backtick-quoted spans and fenced blocks are stripped before matching
 *  (`(`+)…\1` covers inline spans, double-backtick spans, and ``` fences
 *  alike). A mention is `@` + a GitHub-shaped login (alnum + inner hyphens,
 *  ≤39 chars) not preceded by a word character — so `user@example.com`
 *  stays legal, matching GitHub's own linkification rule. Pure + exported
 *  so the refusal is unit-tested, not merely documented. */
export function findRawMentions(body) {
  const prose = String(body ?? "").replace(/(`+)[\s\S]*?\1/g, " ");
  const re = /(^|[^\w`])@([a-zA-Z\d](?:[a-zA-Z\d]|-(?=[a-zA-Z\d])){0,38})/g;
  const found = new Set();
  let m;
  while ((m = re.exec(prose))) found.add(`@${m[2]}`);
  return [...found];
}

function arg(name) {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 && i + 1 < process.argv.length ? process.argv[i + 1] : undefined;
}

function flag(name) {
  return process.argv.includes(`--${name}`);
}

/** All values passed via repeated --label flags. */
function labelArgs() {
  const out = [];
  for (let i = 0; i < process.argv.length; i++) {
    if (process.argv[i] === "--label" && process.argv[i + 1]) out.push(process.argv[i + 1]);
  }
  return [...new Set(out)];
}

/** The label set to stamp. Exported + pure so the invariants are unit-tested,
 *  not merely documented:
 *   - any hand-off to a human carries ESCALATION_LABEL — added whenever the
 *     verdict escalates (the --needs-human flag OR the hidden body marker);
 *   - a 🟢 merge-ready hand-off ALSO carries REVIEWED_LABEL (the --reviewed
 *     flag OR the hidden reviewed marker) — and reviewed never implies escalated
 *     and vice versa; each is its own signal, on top of any explicit --label. */
export function resolveLabels(rawLabels, { needsHuman = false, reviewed = false, body = "" } = {}) {
  const out = [...rawLabels];
  if (needsHuman || body.includes(NEEDS_HUMAN_MARKER)) out.push(ESCALATION_LABEL);
  if (reviewed || body.includes(REVIEWED_MARKER)) out.push(REVIEWED_LABEL);
  return [...new Set(out)];
}

/** Epic-019 Story 1: every hand-off to a human carries WHY. Pure resolver —
 *  given the body plus the --reason/--reason-text flags, returns the reason
 *  codes found, the `autopilot:reason:*` labels to stamp, and the marker to
 *  append to the body (null when it already carries one for that code).
 *  Throws (C-4) on an unknown code, an `other` without free text, or an
 *  escalating comment with no reason at all — an un-reasoned hand-off never
 *  reaches GitHub. */
export function resolveReasons({ body = "", escalating = false, reason, reasonText = "" } = {}) {
  const codes = new Set(findReasonMarkers(body).map((m) => m.code)); // throws on unknown / bare other
  let appendMarker = null;
  if (reason) {
    assertReasonCode(reason);
    if (!codes.has(reason)) {
      appendMarker = reasonMarker(reason, reasonText); // throws on other w/o text
      codes.add(reason);
    }
  }
  if (escalating && codes.size === 0) {
    throw new Error(
      "an autopilot:needs-human hand-off must carry an escalation reason (Epic-019): pass --reason <code> " +
        "(taxonomy: workforce/docs/pr-escalation-reasons.md) or embed the <!-- autopilot:reason:<code> --> " +
        'marker in the body; "other" requires free text via --reason-text.',
    );
  }
  return { codes: [...codes], labels: [...codes].map(reasonLabel), appendMarker };
}

async function gh(token, method, path, body) {
  return fetch(`${GH_API}${path}`, {
    method,
    headers: {
      authorization: `Bearer ${token}`,
      accept: "application/vnd.github+json",
      "content-type": "application/json",
      "x-github-api-version": "2022-11-28",
      "user-agent": "kohuehara-workforce",
    },
    body: body ? JSON.stringify(body) : undefined,
  });
}

async function main() {
  const projectId = arg("project");
  const prNumber = arg("pr");
  const bodyFile = arg("body-file");
  const token = process.env.GITHUB_TOKEN;

  if (!projectId) die(1, "--project <id> is required");
  if (!prNumber || !/^\d+$/.test(prNumber)) die(1, "--pr <number> is required (positive integer)");
  if (!bodyFile) die(1, "--body-file <path> is required");
  if (!token) die(2, "GITHUB_TOKEN env is required (from credentials['github.token'].token)");

  let owner, repo, body;
  try {
    ({ owner, repo } = projectRepo(REPO_ROOT, projectId));
  } catch (e) {
    die(1, e.message);
  }
  try {
    body = readFileSync(bodyFile, "utf8");
  } catch {
    die(1, `body-file unreadable: ${bodyFile}`);
  }
  if (body.trim().length === 0) die(1, "body-file is empty — refusing to post an empty routing comment (W-4)");
  const rawMentions = findRawMentions(body);
  if (rawMentions.length > 0) {
    die(
      1,
      `body contains raw GitHub @-mention(s): ${rawMentions.join(", ")} — persona slugs are not GitHub ` +
        `accounts and a raw @ notifies the real, unrelated user who owns that name (ML-012). ` +
        "Reference agents as `wf:<slug>` and wrap any literal @token in backticks.",
    );
  }

  // Epic-019: resolve labels + reasons BEFORE posting — the reason marker must
  // ride in the comment body, and an un-reasoned / mis-coded escalation must
  // fail loud here (C-4) without posting anything.
  let labels = resolveLabels(labelArgs(), {
    needsHuman: flag("needs-human"),
    reviewed: flag("reviewed"),
    body,
  });
  let reasons;
  try {
    reasons = resolveReasons({
      body,
      escalating: labels.includes(ESCALATION_LABEL),
      reason: arg("reason"),
      reasonText: arg("reason-text") ?? "",
    });
  } catch (e) {
    die(1, e instanceof Error ? e.message : String(e));
  }
  if (reasons.appendMarker) body = `${body.trimEnd()}\n\n${reasons.appendMarker}\n`;
  labels = [...new Set([...labels, ...reasons.labels])];

  // Verdict-time L0/L1 computation (Epic-019): every escalation records
  // whether the PR touches the target's declared L0/L1 set — today only the
  // merge leg computes this, which makes the funnel's eligible (non-L0/L1)
  // share uncomputable. Same fail-closed source as the merge engine
  // (prTouchesL0L1 → resolveL0L1Paths): an unreadable/markerless governance
  // doc means the set is UNKNOWN — log and escalate without an eligibility
  // record, never guess. A telemetry failure must not block the hand-off
  // itself (escalating IS the safe direction).
  if (labels.includes(ESCALATION_LABEL)) {
    try {
      const t = await prTouchesL0L1(makeGh({ token, userAgent: "kohuehara-workforce" }), `${owner}/${repo}`, prNumber);
      if (t.known && t.touches) labels = [...new Set([...labels, reasonLabel("l0l1-path")])];
      else if (!t.known) console.error(`pr-autopilot-post: WARN L0/L1 set unknown for ${owner}/${repo}#${prNumber} (${t.why}) — escalating without an eligibility record`);
    } catch (e) {
      console.error(`pr-autopilot-post: WARN verdict-time L0/L1 check failed (${e?.msg || e?.message || e}) — escalating without an eligibility record`);
    }
  }

  // Bounded flaky-check auto-rerun (Epic-019 Story 2c). A `checks-failing`
  // escalation first offers the failing checks ONE rerun — only when EVERY
  // failing check is on the evidenced, unexpired allowlist (flaky-checks.json)
  // and this PR has never been rerun (the hidden <!-- autopilot:rerun:… -->
  // marker is the once-ever latch). A triggered rerun posts its own audit
  // comment + `autopilot:reran` label and DEFERS this escalation (exit 0
  // without posting the verdict) — the next tick re-verdicts on fresh checks.
  // Every other state (non-allowlisted, editorial/deploy-class — those are
  // categorically ineligible — expired entry, prior rerun, ambiguity, or the
  // attempt itself throwing) falls through to the escalation, which is the
  // loud direction (C-4). The R-N10 merge predicate is untouched.
  if (labels.includes(ESCALATION_LABEL) && reasons.codes.includes("checks-failing")) {
    try {
      const rr = await attemptFlakyRerun(makeGh({ token, userAgent: "kohuehara-workforce" }), `${owner}/${repo}`, prNumber);
      if (rr.reran) {
        console.log(
          `pr-autopilot-post: flaky rerun triggered on ${owner}/${repo}#${prNumber} (${rr.checks.join(", ")}) — ` +
            `checks-failing escalation deferred to the post-rerun verdict (max 1 rerun per PR)`,
        );
        process.exit(0);
      }
      console.error(`pr-autopilot-post: no flaky rerun (${rr.why}) — escalating checks-failing`);
    } catch (e) {
      console.error(`pr-autopilot-post: WARN flaky-rerun attempt failed (${e?.msg || e?.message || e}) — escalating checks-failing`);
    }
  }

  let res;
  try {
    res = await fetch(`${GH_API}/repos/${owner}/${repo}/issues/${prNumber}/comments`, {
      method: "POST",
      headers: {
        authorization: `Bearer ${token}`,
        accept: "application/vnd.github+json",
        "content-type": "application/json",
        "x-github-api-version": "2022-11-28",
        "user-agent": "kohuehara-workforce",
      },
      body: JSON.stringify({ body }),
    });
  } catch (e) {
    die(3, `network error: ${e instanceof Error ? e.message : String(e)}`);
  }
  if (res.status === 201) {
    const json = await res.json().catch(() => ({}));
    console.log(`pr-autopilot-post: posted to ${owner}/${repo}#${prNumber} (comment ${json.id ?? "?"})`);
    // Stamp escalation + reason labels (best-effort: a label problem must not
    // fail a comment that already landed). Auto-create any label the repo
    // lacks. `labels` was resolved above, before the post: resolveLabels
    // guarantees ESCALATION_LABEL whenever this comment hands the PR to a
    // human, and resolveReasons/prTouchesL0L1 supply the autopilot:reason:*
    // family.
    if (labels.length > 0) {
      for (const name of labels) {
        const meta = LABEL_META[name] ?? (name.startsWith(REASON_LABEL_PREFIX) ? REASON_LABEL_META : FALLBACK_LABEL_META);
        const cr = await gh(token, "POST", `/repos/${owner}/${repo}/labels`, {
          name, color: meta.color, description: meta.description,
        }).catch(() => ({ status: 0 }));
        if (cr.status !== 201 && cr.status !== 422) {
          console.error(`pr-autopilot-post: WARN ensure label "${name}" → HTTP ${cr.status}`);
        }
      }
      const lr = await gh(token, "POST", `/repos/${owner}/${repo}/issues/${prNumber}/labels`, { labels }).catch(() => ({ status: 0 }));
      if (lr.status === 200) console.log(`pr-autopilot-post: labelled #${prNumber} [${labels.join(", ")}]`);
      else console.error(`pr-autopilot-post: WARN could not label #${prNumber} → HTTP ${lr.status}`);
    }
    process.exit(0);
  }
  const text = await res.text().catch(() => "");
  die(res.status < 500 ? 2 : 3, `POST comment → ${res.status}: ${text.slice(0, 300)}`);
}

function die(code, msg) {
  console.error(`pr-autopilot-post: ${msg}`);
  process.exit(code);
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? "").href) {
  main().catch((e) => die(3, e instanceof Error ? e.message : String(e)));
}

// @ts-nocheck — the script under test (pr-autopilot-scan.mjs) is a
// dependency-free ESM script, not TS; vitest/esbuild imports it fine at
// runtime, and this suite is not shipped code. Discovered by
// workforce/lambdas/vitest.config.mjs (`include: ["../skills/**/*-tests.ts"]`),
// so `cd workforce/lambdas && npm test` runs it.
//
// Locks Epic-019 Story 2b (nomination load cap): a persona holds at most
// NOMINATION_SEAT_CAP concurrent open lens-review seats (one per open,
// non-terminal PR whose routing comment nominates its `wf:<slug>`); the cap
// filter replaces a capped persona with another eligible one, and when no ≥3
// panel can be seated it escalates with the existing taxonomy code
// `cannot-seat-panel` — never a quiet under-sized panel.
import { describe, it, expect } from "vitest";
import {
  NOMINATION_SEAT_CAP,
  countOpenSeats,
  applyNominationCap,
  alreadyRouted,
  withinWindow,
} from "./pr-autopilot-scan.mjs";
import { MIN_REVIEWERS } from "./pr-merge.mjs";

// The SKILL.md Step 2 routing-comment shape (nomination bullets + skip line).
const routingComment = (slugs, skipped = []) =>
  [
    "**Nadia — cycle 1 of ≤ 7.**",
    "",
    "Summary…",
    "",
    "Reviewers nominated (≥ 3):",
    "",
    ...slugs.map((s) => `- **\`wf:${s}\`** — owns this surface`),
    "",
    ...skipped.map((s) => `Skipping \`wf:${s}\` — no surface.`),
  ].join("\n");

describe("countOpenSeats — seats from wf:<slug> nomination markers on open PRs", () => {
  it("counts one seat per persona per open PR", () => {
    const counts = countOpenSeats([
      { labels: [], bodies: [routingComment(["dario", "ren", "mateo"])] },
      { labels: [], bodies: [routingComment(["dario", "hana", "yuki"])] },
    ]);
    expect(counts).toEqual({ dario: 2, ren: 1, mateo: 1, hana: 1, yuki: 1 });
  });
  it("a cycle-2 re-route on the same PR is the same seat, not a second one", () => {
    const counts = countOpenSeats([
      { labels: [], bodies: [routingComment(["dario", "ren", "mateo"]), routingComment(["dario", "ren", "mateo"])] },
    ]);
    expect(counts.dario).toBe(1);
  });
  it("terminal/paused PRs release their seats (needs-human / autopilot:off)", () => {
    const counts = countOpenSeats([
      { labels: ["autopilot:needs-human"], bodies: [routingComment(["dario", "ren", "mateo"])] },
      { labels: ["Autopilot:Off"], bodies: [routingComment(["dario"])] },
      { labels: ["some-other-label"], bodies: [routingComment(["dario", "ren", "mateo"])] },
    ]);
    expect(counts).toEqual({ dario: 1, ren: 1, mateo: 1 });
  });
  it("skip lines, green markers, sign-offs, and prose wf: mentions are not seats", () => {
    const counts = countOpenSeats([
      {
        labels: [],
        bodies: [
          routingComment(["dario", "ren", "mateo"], ["maya"]),
          "looks good\n<!-- autopilot:review:hana:green -->",
          "— Yuki (LLM persona; lens: platform; manual route via pr-autopilot)",
          "as `wf:celeste` noted in the verdict…",
        ],
      },
    ]);
    expect(counts).toEqual({ dario: 1, ren: 1, mateo: 1 });
  });
  it("is case-insensitive on the slug and tolerates * bullets", () => {
    const counts = countOpenSeats([{ labels: [], bodies: ["* **`wf:Dario`** — surface"] }]);
    // The nomination-bullet slug charset is lowercase (persona slugs are);
    // `wf:Dario` would not be written by the template — but a lowercase slug
    // behind a * bullet still counts.
    expect(countOpenSeats([{ labels: [], bodies: ["* **`wf:dario`** — surface"] }])).toEqual({ dario: 1 });
    expect(counts).toEqual({});
  });
  it("empty inputs count nothing", () => {
    expect(countOpenSeats([])).toEqual({});
    expect(countOpenSeats([{ labels: [], bodies: [] }])).toEqual({});
  });
});

describe("applyNominationCap — the Step 2 mechanical cap filter", () => {
  const candidates = ["dario", "ren", "mateo", "hana"];

  it("under the cap: everyone stays eligible, panel seatable", () => {
    const r = applyNominationCap(candidates, { dario: 2, ren: 0 });
    expect(r.eligible).toEqual(candidates);
    expect(r.overCap).toEqual([]);
    expect(r.canSeatPanel).toBe(true);
    expect(r.escalateWith).toBeNull();
  });
  it("AT the cap is capped: holding NOMINATION_SEAT_CAP seats means no new nomination", () => {
    const r = applyNominationCap(candidates, { dario: NOMINATION_SEAT_CAP });
    expect(r.eligible).toEqual(["ren", "mateo", "hana"]);
    expect(r.overCap).toEqual([{ slug: "dario", openSeats: NOMINATION_SEAT_CAP }]);
    expect(r.canSeatPanel).toBe(true); // the router picks another persona
  });
  it("over the cap is capped too", () => {
    const r = applyNominationCap(candidates, { dario: NOMINATION_SEAT_CAP + 3 });
    expect(r.overCap).toEqual([{ slug: "dario", openSeats: NOMINATION_SEAT_CAP + 3 }]);
  });
  it("no seatable ≥3 panel → escalateWith the existing cannot-seat-panel code", () => {
    const r = applyNominationCap(candidates, { dario: 5, ren: 6, mateo: 9 });
    expect(r.eligible).toEqual(["hana"]);
    expect(r.eligible.length).toBeLessThan(MIN_REVIEWERS);
    expect(r.canSeatPanel).toBe(false);
    expect(r.escalateWith).toBe("cannot-seat-panel");
  });
  it("de-dupes and case-folds candidate slugs; unknown personas count 0 seats", () => {
    const r = applyNominationCap(["Dario", "dario", " ren ", "newbie"], { dario: 1 });
    expect(r.eligible).toEqual(["dario", "ren", "newbie"]);
  });
  it("a custom cap is honoured", () => {
    const r = applyNominationCap(candidates, { dario: 2 }, 2);
    expect(r.overCap).toEqual([{ slug: "dario", openSeats: 2 }]);
  });
  it("throws (C-4) on a broken cap or candidate list — never silently un-caps", () => {
    expect(() => applyNominationCap(candidates, {}, 0)).toThrow(/positive integer/);
    expect(() => applyNominationCap(candidates, {}, 2.5)).toThrow(/positive integer/);
    expect(() => applyNominationCap("dario", {})).toThrow(/array/);
  });
});

// Guard the pre-existing pure helpers this suite now shares a file with —
// they had no coverage before the Story-2b change touched the module.
describe("alreadyRouted / withinWindow (existing discovery gates)", () => {
  it("alreadyRouted matches the persona's cycle-opening marker", () => {
    expect(alreadyRouted([{ body: "**Nadia — cycle 1 of ≤ 7.**\n…" }], "nadia")).toBe(true);
    expect(alreadyRouted([{ body: "**Maya — cycle 1 of ≤ 7.**" }], "nadia")).toBe(false);
    expect(alreadyRouted([], "nadia")).toBe(false);
  });
  it("withinWindow gates on the recency window", () => {
    const now = Date.parse("2026-07-08T00:00:00Z");
    expect(withinWindow("2026-07-05T00:00:00Z", 7, now)).toBe(true);
    expect(withinWindow("2026-06-20T00:00:00Z", 7, now)).toBe(false);
    expect(withinWindow("not-a-date", 7, now)).toBe(false);
  });
});

#!/usr/bin/env node
// Deterministic pr-autopilot SCAN script — GET-only discovery for the CCR
// cron-poll routing leg (ADR-0005). The CCR session runs this first to
// learn WHICH open PRs in the bound project's repo still need a cycle-1
// routing comment; it then applies the persona's nomination_rules (its
// judgment) and posts each routing comment via pr-autopilot-post.mjs.
//
// This script performs NO writes — it only issues GitHub GETs:
//   - list open PRs in the project repo
//   - read each PR's issue comments (to skip already-routed PRs)
//   - read each candidate PR's unified diff
// The (project × agent × skill) binding supplies project_id; the
// project linkage supplies the github.token (injected as GITHUB_TOKEN).
// The repo (owner/repo) is read from the in-repo project.json — the CCR
// session runs inside the workforce checkout.
//
// Discovery includes BOTH draft and non-draft PRs, and BOTH human- and
// bot-authored (Dependabot) PRs — every open PR in the window is routable
// (2026-06-17 Autopilot widening, adr-0010). The only discovery filters are
// the recency window and "already routed this cycle".
//
// NOMINATION LOAD CAP (Epic-019 Story 2b — fairness + W-3). Auto-nomination
// must not degenerate into "the same 3 reviewers on everything": a persona
// may hold at most NOMINATION_SEAT_CAP concurrent OPEN lens-review seats,
// computed mechanically from the `wf:<slug>` nomination markers in routing
// comments on open, non-terminal PRs. The scan emits `open_seat_counts` (and
// `capped_personas`) in its output; the routing persona runs its candidate
// panel through applyNominationCap() and seats only the eligible remainder.
// When the cap leaves no seatable ≥3 panel, the PR escalates with reason
// `cannot-seat-panel` (taxonomy v1 — an existing code, new emission site).
//
// Usage:
//   GITHUB_TOKEN=<credentials['github.token'].token> \
//     node workforce/skills/pr-autopilot/pr-autopilot-scan.mjs \
//       --project asp-cloud --persona nadia \
//       [--max 5] [--since-days 7] [--out /tmp/pr-autopilot-candidates.json]
//
// Output: writes a JSON array of candidate PRs to --out and prints a
// one-line summary to stdout. Exit 0 even when zero candidates (a valid
// "nothing to route this tick" outcome — the session then does nothing).
//
// Exit codes:
//   0  — scan completed (candidates written; may be an empty array)
//   1  — bad args / project.json missing or has no github.{owner,repo}
//   2  — GitHub auth/4xx (token missing or lacks repo read)
//   3  — network / unexpected error

import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath, pathToFileURL } from "node:url";
import { dirname, join } from "node:path";
import { ESCALATION_LABEL, MIN_REVIEWERS } from "./pr-merge.mjs";
import { assertReasonCode } from "./escalation-reasons.mjs";

const GH_API = "https://api.github.com";
const MAX_DIFF_CHARS = 48_000; // ~12K tokens; protects the CCR context budget
const HERE = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = join(HERE, "..", "..", ".."); // workforce/skills/pr-autopilot → repo root

function arg(name, fallback) {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 && i + 1 < process.argv.length ? process.argv[i + 1] : fallback;
}

/** Resolve the project's GitHub surface from the in-repo project.json. */
export function projectRepo(repoRoot, projectId) {
  const path = join(repoRoot, "workforce", "projects", projectId, "project.json");
  let json;
  try {
    json = JSON.parse(readFileSync(path, "utf8"));
  } catch {
    throw new Error(`pr-autopilot-scan: project.json not found for "${projectId}" at ${path}`);
  }
  if (!json.github || !json.github.owner || !json.github.repo) {
    throw new Error(
      `pr-autopilot-scan: project "${projectId}" declares no github.{owner,repo} — pr-autopilot needs an external project repo`,
    );
  }
  return { owner: json.github.owner, repo: json.github.repo };
}

/** A PR has already been routed (this cycle leg) if a comment from this
 *  persona opens with the router-comment marker. Mirrors the marker that
 *  pr-autopilot-post writes via the SKILL.md comment template. */
export function alreadyRouted(comments, personaSlug) {
  const personaName = personaSlug.charAt(0).toUpperCase() + personaSlug.slice(1);
  const marker = new RegExp(`^\\*\\*${personaName} — cycle \\d+ of `, "m");
  return comments.some((c) => marker.test(c.body ?? ""));
}

/** Recency gate: only route PRs updated within the window (avoids
 *  mass-commenting a stale backlog on first cron tick). */
export function withinWindow(updatedAt, sinceDays, now = Date.now()) {
  const t = Date.parse(updatedAt);
  if (Number.isNaN(t)) return false;
  return now - t <= sinceDays * 24 * 60 * 60 * 1000;
}

// ── Nomination load cap (Epic-019 Story 2b) ─────────────────────────────────

/** Max concurrent open lens-review seats one persona may hold. Operator knob:
 *  raising it widens per-persona load; the panel floor (MIN_REVIEWERS) is the
 *  merge engine's, never this. */
export const NOMINATION_SEAT_CAP = 5;

// A nomination SEAT is the routing-comment bullet from the SKILL.md Step 2
// template: `- **`wf:<persona>`** — <rationale>`. Skip-lines ("Skipping
// `wf:x` — …"), review sign-offs, and green markers never match.
const NOMINATION_BULLET_RE = /^\s*[-*]\s+\*\*`wf:([a-z][a-z0-9-]*)`\*\*/gmu;

/** Pure seat counter. Given every OPEN PR's { labels, bodies } (issue-comment
 *  bodies — routing comments live there), return { slug → open seat count }.
 *  A persona holds ONE seat per open PR that nominates it (a cycle-2 re-route
 *  is the same seat, not a second one). Terminal/paused PRs release their
 *  seats: `autopilot:needs-human` (escalated — the human's queue now) and
 *  `autopilot:off` (maintainer pause) are skipped; merged/closed PRs are not
 *  in the open list at all. */
export function countOpenSeats(openPrs) {
  const counts = {};
  for (const pr of openPrs ?? []) {
    const names = (pr.labels ?? []).map((l) => String(l || "").toLowerCase());
    if (names.includes(ESCALATION_LABEL) || names.includes("autopilot:off")) continue;
    const seated = new Set();
    for (const b of pr.bodies ?? []) {
      const re = new RegExp(NOMINATION_BULLET_RE.source, "gmu");
      let m;
      while ((m = re.exec(String(b ?? ""))) !== null) seated.add(m[1].toLowerCase());
    }
    for (const slug of seated) counts[slug] = (counts[slug] ?? 0) + 1;
  }
  return counts;
}

/** Pure cap filter — the mechanical half of the Step 2 routing contract.
 *  Given the persona's candidate reviewer slugs (preference-ordered), the
 *  open seat counts (countOpenSeats), and the cap, return:
 *    - eligible:   candidates still under the cap (order preserved, de-duped,
 *                  case-folded) — seat the panel from these;
 *    - overCap:    [{ slug, openSeats }] the cap excluded — the router picks
 *                  another eligible persona instead;
 *    - canSeatPanel: eligible.length >= MIN_REVIEWERS (the merge engine's
 *                  panel floor);
 *    - escalateWith: null, or "cannot-seat-panel" (taxonomy v1) when no ≥3
 *                  panel can be seated under the cap.
 *  Throws (C-4) on a non-positive/non-integer cap or a non-array candidate
 *  list — a misconfigured cap must never silently un-cap. */
export function applyNominationCap(candidates, openSeatCounts = {}, cap = NOMINATION_SEAT_CAP) {
  if (!Number.isInteger(cap) || cap < 1) {
    throw new Error(`applyNominationCap: cap must be a positive integer (got ${cap}) — a broken cap never silently un-caps (C-4)`);
  }
  if (!Array.isArray(candidates)) {
    throw new Error("applyNominationCap: candidates must be an array of persona slugs (C-4)");
  }
  const seen = new Set();
  const eligible = [];
  const overCap = [];
  for (const raw of candidates) {
    const slug = String(raw ?? "").trim().toLowerCase();
    if (!slug || seen.has(slug)) continue;
    seen.add(slug);
    const openSeats = Number(openSeatCounts[slug] ?? 0);
    if (openSeats >= cap) overCap.push({ slug, openSeats });
    else eligible.push(slug);
  }
  const canSeatPanel = eligible.length >= MIN_REVIEWERS;
  return {
    eligible,
    overCap,
    canSeatPanel,
    escalateWith: canSeatPanel ? null : assertReasonCode("cannot-seat-panel"),
  };
}

async function ghGet(token, path, accept) {
  const res = await fetch(`${GH_API}${path}`, {
    headers: {
      authorization: `Bearer ${token}`,
      accept: accept ?? "application/vnd.github+json",
      "x-github-api-version": "2022-11-28",
      "user-agent": "kohuehara-workforce",
    },
  });
  if (!res.ok) {
    const body = await res.text();
    const err = new Error(`GitHub GET ${path} → ${res.status}: ${body.slice(0, 300)}`);
    err.httpStatus = res.status;
    throw err;
  }
  return accept?.includes("vnd.github.v3.diff") ? res.text() : res.json();
}

async function main() {
  const projectId = arg("project");
  const persona = arg("persona");
  const max = Number(arg("max", "5"));
  const sinceDays = Number(arg("since-days", "7"));
  const out = arg("out", "/tmp/pr-autopilot-candidates.json");
  const token = process.env.GITHUB_TOKEN;

  if (!projectId) die(1, "--project <id> is required");
  if (!persona) die(1, "--persona <agent-slug> is required (the routing persona)");
  if (!token) die(2, "GITHUB_TOKEN env is required (from credentials['github.token'].token)");
  if (!Number.isInteger(max) || max < 1) die(1, `--max must be a positive integer (got ${max})`);

  let owner, repo;
  try {
    ({ owner, repo } = projectRepo(REPO_ROOT, projectId));
  } catch (e) {
    die(1, e.message);
  }

  // List ALL open PRs (draft + non-draft, human + bot), most-recently-updated
  // first. Draft/bot are no longer discovery filters (adr-0010).
  let prs;
  try {
    prs = await ghGet(token, `/repos/${owner}/${repo}/pulls?state=open&sort=updated&direction=desc&per_page=50`);
  } catch (e) {
    die(e.httpStatus && e.httpStatus < 500 ? 2 : 3, e.message);
  }

  // Nomination load cap (Epic-019 Story 2b): seat counts span EVERY open PR's
  // routing comments, not just this tick's candidates — so fetch each open
  // PR's comments once, up front, and reuse them for the already-routed check.
  const commentsByPr = new Map();
  for (const pr of prs) {
    try {
      commentsByPr.set(pr.number, await ghGet(token, `/repos/${owner}/${repo}/issues/${pr.number}/comments?per_page=100`));
    } catch (e) {
      die(e.httpStatus && e.httpStatus < 500 ? 2 : 3, e.message);
    }
  }
  const openSeatCounts = countOpenSeats(
    prs.map((pr) => ({
      labels: Array.isArray(pr.labels) ? pr.labels.map((l) => l?.name) : [],
      bodies: (commentsByPr.get(pr.number) ?? []).map((c) => c.body),
    })),
  );
  const cappedPersonas = Object.entries(openSeatCounts)
    .filter(([, n]) => n >= NOMINATION_SEAT_CAP)
    .map(([slug]) => slug)
    .sort();

  const candidates = [];
  for (const pr of prs) {
    if (candidates.length >= max) break;
    // Draft and bot-authored PRs are IN scope (adr-0010): drafts get an early
    // review pass, and Dependabot PRs route through the same review→consensus
    // →merge path as human PRs (the dependabot-triage no-review lane retires).
    if (!withinWindow(pr.updated_at, sinceDays)) continue;
    const comments = commentsByPr.get(pr.number) ?? [];
    if (alreadyRouted(comments, persona)) continue;

    let diff;
    try {
      diff = await ghGet(token, `/repos/${owner}/${repo}/pulls/${pr.number}`, "application/vnd.github.v3.diff");
    } catch (e) {
      die(e.httpStatus && e.httpStatus < 500 ? 2 : 3, e.message);
    }
    if (diff.length > MAX_DIFF_CHARS) {
      diff = diff.slice(0, MAX_DIFF_CHARS) + `\n\n... [diff truncated at ${MAX_DIFF_CHARS} chars] ...\n`;
    }
    candidates.push({
      number: pr.number,
      title: pr.title,
      body: pr.body ?? "",
      author: pr.user?.login ?? "(unknown)",
      draft: pr.draft === true,
      is_bot: pr.user?.type === "Bot" || /\[bot\]$/.test(pr.user?.login ?? ""),
      base: pr.base?.ref ?? "",
      head: pr.head?.ref ?? "",
      html_url: pr.html_url,
      updated_at: pr.updated_at,
      comments: comments
        .slice(0, 30)
        .map((c) => ({ author: c.user?.login ?? "(unknown)", body: (c.body ?? "").slice(0, 240).replace(/\n+/g, " ") })),
      diff,
    });
  }

  writeFileSync(
    out,
    JSON.stringify(
      {
        project_id: projectId,
        owner,
        repo,
        persona,
        // Epic-019 Story 2b: the routing persona filters its panel through
        // applyNominationCap(candidates, open_seat_counts) — capped_personas
        // (seats >= nomination_cap) are not nominatable this tick.
        nomination_cap: NOMINATION_SEAT_CAP,
        open_seat_counts: openSeatCounts,
        capped_personas: cappedPersonas,
        candidates,
      },
      null,
      2,
    ),
  );
  console.log(
    `pr-autopilot-scan: ${owner}/${repo} — ${candidates.length} candidate PR(s) need cycle-1 routing (scanned ${prs.length} open, max ${max}, window ${sinceDays}d; ` +
      `seat cap ${NOMINATION_SEAT_CAP}, capped: ${cappedPersonas.length > 0 ? cappedPersonas.join(", ") : "none"}) → ${out}`,
  );
  process.exit(0);
}

function die(code, msg) {
  console.error(`pr-autopilot-scan: ${msg}`);
  process.exit(code);
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? "").href) {
  main().catch((e) => die(3, e instanceof Error ? e.message : String(e)));
}

// @ts-nocheck — the script under test (pr-autopilot-sweep.mjs) is a
// dependency-free ESM script, not TS; vitest/esbuild imports it fine at
// runtime, and this suite is not shipped code. Discovered by
// workforce/lambdas/vitest.config.mjs (`include: ["../skills/**/*-tests.ts"]`),
// so `cd workforce/lambdas && npm test` runs it.
//
// Locks the TWO-OUTCOME contract mechanically: every open PR in autopilot scope
// is either in an active cycle, or terminal (merged / labelled
// autopilot:needs-human). classifySweep is the pure decision — it must catch
// all three "neither" classes (ML-009 label drops, stalled cycles, PRs that
// aged out of the discovery window) and must never flag paused (autopilot:off)
// or already-escalated PRs.
import { describe, it, expect } from "vitest";
import {
  classifySweep,
  sweepHandoffBody,
  DEFAULT_STALE_HOURS,
  DEFAULT_WINDOW_DAYS,
} from "./pr-autopilot-sweep.mjs";
import { NEEDS_HUMAN_MARKER } from "./pr-autopilot-post.mjs";
import { ESCALATION_LABEL } from "./pr-merge.mjs";

const NOW = Date.parse("2026-07-01T12:00:00Z");
const hoursAgo = (h) => new Date(NOW - h * 3600_000).toISOString();
const daysAgo = (d) => hoursAgo(d * 24);
const ROUTING_COMMENT = "**Nadia — cycle 1 of ≤ 3.**\n\nReviewers nominated (≥ 3): …";
const opts = { now: NOW };

describe("classifySweep — terminal / paused PRs are never violations", () => {
  it("already-escalated PR (label present) is terminal", () => {
    expect(
      classifySweep(
        { createdAt: daysAgo(30), updatedAt: daysAgo(30), labels: [ESCALATION_LABEL], bodies: [ROUTING_COMMENT] },
        opts,
      ),
    ).toBeNull();
  });

  it("autopilot:off pauses the sweep for that PR, however stale", () => {
    expect(
      classifySweep(
        { createdAt: daysAgo(90), updatedAt: daysAgo(90), labels: ["Autopilot:OFF"], bodies: [] },
        opts,
      ),
    ).toBeNull();
  });

  it("label matching is case-insensitive (GitHub labels preserve case)", () => {
    expect(
      classifySweep(
        { createdAt: daysAgo(30), updatedAt: daysAgo(30), labels: ["Autopilot:Needs-Human"], bodies: [ROUTING_COMMENT] },
        opts,
      ),
    ).toBeNull();
  });
});

describe("classifySweep — unlabelled-handoff (ML-009)", () => {
  it("a hand-off marker with no label is a violation regardless of age", () => {
    expect(
      classifySweep(
        { createdAt: hoursAgo(1), updatedAt: hoursAgo(1), labels: [], bodies: [`verdict…\n${NEEDS_HUMAN_MARKER}`] },
        opts,
      ),
    ).toBe("unlabelled-handoff");
  });

  it("marker in a review body (not just an issue comment) also counts", () => {
    expect(
      classifySweep(
        { createdAt: hoursAgo(2), updatedAt: hoursAgo(2), labels: [], bodies: ["", `escalating — ${NEEDS_HUMAN_MARKER}`] },
        opts,
      ),
    ).toBe("unlabelled-handoff");
  });
});

describe("classifySweep — stale-routed (a cycle that never terminated)", () => {
  it("routed + untouched past the stale threshold escalates", () => {
    expect(
      classifySweep(
        { createdAt: daysAgo(5), updatedAt: hoursAgo(DEFAULT_STALE_HOURS + 1), labels: [], bodies: [ROUTING_COMMENT] },
        opts,
      ),
    ).toBe("stale-routed");
  });

  it("routed but recently updated stays in-cycle (author may still revise)", () => {
    expect(
      classifySweep(
        { createdAt: daysAgo(5), updatedAt: hoursAgo(DEFAULT_STALE_HOURS - 1), labels: [], bodies: [ROUTING_COMMENT] },
        opts,
      ),
    ).toBeNull();
  });

  it("honours a custom --stale-hours", () => {
    const pr = { createdAt: daysAgo(2), updatedAt: hoursAgo(13), labels: [], bodies: [ROUTING_COMMENT] };
    expect(classifySweep(pr, { now: NOW, staleHours: 12 })).toBe("stale-routed");
    expect(classifySweep(pr, { now: NOW, staleHours: 24 })).toBeNull();
  });
});

describe("classifySweep — never-routed (aged out of the discovery window)", () => {
  it("unrouted + older than the window escalates (the scan will never see it)", () => {
    expect(
      classifySweep(
        { createdAt: daysAgo(20), updatedAt: daysAgo(DEFAULT_WINDOW_DAYS + 1), labels: [], bodies: ["just chatter"] },
        opts,
      ),
    ).toBe("never-routed");
  });

  it("unrouted but still inside the window is left to the cadence", () => {
    expect(
      classifySweep(
        { createdAt: daysAgo(20), updatedAt: daysAgo(DEFAULT_WINDOW_DAYS - 1), labels: [], bodies: [] },
        opts,
      ),
    ).toBeNull();
  });

  it("a fresh PR with no comments is not a violation", () => {
    expect(classifySweep({ createdAt: hoursAgo(1), updatedAt: hoursAgo(1), labels: [], bodies: [] }, opts)).toBeNull();
  });

  it("unparseable timestamps are left alone (fail-safe for the write path)", () => {
    expect(classifySweep({ createdAt: "n/a", updatedAt: "n/a", labels: [], bodies: [] }, opts)).toBeNull();
  });
});

describe("sweepHandoffBody — the escalation comment is a real hand-off", () => {
  it("carries the hidden needs-human marker (so ML-009 tooling recognises it)", () => {
    for (const kind of ["unlabelled-handoff", "stale-routed", "never-routed"]) {
      const body = sweepHandoffBody(kind, { staleHours: 48, windowDays: 7 });
      expect(body).toContain(NEEDS_HUMAN_MARKER);
      expect(body.trim().length).toBeGreaterThan(50);
    }
  });

  it("names the reason class in prose", () => {
    expect(sweepHandoffBody("stale-routed", { staleHours: 48, windowDays: 7 })).toContain("48h");
    expect(sweepHandoffBody("never-routed", { staleHours: 48, windowDays: 7 })).toContain("7-day");
    expect(sweepHandoffBody("unlabelled-handoff", { staleHours: 48, windowDays: 7 })).toContain("ML-009");
  });

  // Epic-019 Story 1: the sweep kind IS the escalation-reason code, reused
  // VERBATIM inside the hidden reason marker — never flattened or renamed.
  it("embeds the Epic-019 reason marker with the kind verbatim", () => {
    for (const kind of ["unlabelled-handoff", "stale-routed", "never-routed"]) {
      expect(sweepHandoffBody(kind, { staleHours: 48, windowDays: 7 })).toContain(
        `<!-- autopilot:reason:${kind} -->`,
      );
    }
  });
});

#!/usr/bin/env node
// pr-autopilot/pr-autopilot-sweep.mjs — the deterministic TERMINAL-STATE sweep.
//
// The pr-autopilot contract is two-outcome: every PR the cadence touches ends
// either **merged** or **escalated with the `autopilot:needs-human` label**.
// The cadence's judgment leg can fail to get there (a run that stalls after the
// routing comment, a 🟡 verdict whose author never revises, a session-driven
// hand-off that bypassed the label stamper — ML-009, or a pr-merge.mjs refusal
// nobody converted into a hand-off). This script closes every one of those gaps
// mechanically: it re-checks PR *state*, not the code path that produced it.
//
// Violation classes (pure, unit-tested in pr-autopilot-sweep-tests.ts):
//   - unlabelled-handoff  a comment/review carries `<!-- autopilot:needs-human -->`
//                         but the PR lacks the label (ML-009).
//   - stale-routed        a routing comment exists, but the PR reached no
//                         terminal state (not merged, not labelled) and has not
//                         been updated for --stale-hours (default 48).
//   - never-routed        no routing comment at all and the PR has fallen out of
//                         the scan's --window-days discovery window (default 7)
//                         — the cadence will never pick it up again on its own.
//
// Skipped (never violations): PRs labelled `autopilot:off` (maintainer pause)
// and PRs already labelled `autopilot:needs-human` (already terminal).
//
// Modes:
//   default   — report violations, exit 2 if any (CI / audit usage).
//   --apply   — enforce the contract: post the hand-off comment (hidden
//               needs-human marker + Epic-019 reason marker) and stamp
//               `autopilot:needs-human` + `autopilot:reason:<kind>` on every
//               violation, so the operator's `is:open
//               label:autopilot:needs-human` queue is complete and every
//               escalation carries its reason. Exit 0 when everything applied.
//
// Usage:
//   GITHUB_TOKEN=... node workforce/skills/pr-autopilot/pr-autopilot-sweep.mjs \
//     --repo <owner>/<repo> [--apply] [--stale-hours 48] [--window-days 7] [--json]
//   (or --project <id> to resolve the repo from workforce/projects/{id}/project.json)
//
// Exit codes: 0 clean / all applied · 1 bad args · 2 violations found (check
// mode) or an apply write failed · 3 network / unexpected.

import { fileURLToPath, pathToFileURL } from "node:url";
import { dirname, join } from "node:path";
import { projectRepo } from "./pr-autopilot-scan.mjs";
import { ESCALATION_LABEL, countRouterCycles, ensureLabels, makeGh } from "./pr-merge.mjs";
import { NEEDS_HUMAN_MARKER } from "./pr-autopilot-post.mjs";
import { reasonLabel, reasonMarker } from "./escalation-reasons.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = join(HERE, "..", "..", "..");
const AUTOPILOT_OFF_LABEL = "autopilot:off";

export const DEFAULT_STALE_HOURS = 48;
export const DEFAULT_WINDOW_DAYS = 7;

/**
 * Pure classifier. Given one open PR's state, return the violation class or
 * null. `bodies` is every issue-comment + review body on the PR.
 */
export function classifySweep(
  { createdAt, updatedAt, labels = [], bodies = [] },
  { now = Date.now(), staleHours = DEFAULT_STALE_HOURS, windowDays = DEFAULT_WINDOW_DAYS } = {},
) {
  const names = labels.map((l) => String(l || "").toLowerCase());
  if (names.includes(AUTOPILOT_OFF_LABEL)) return null; // maintainer pause
  if (names.includes(ESCALATION_LABEL)) return null; // already terminal (escalated)

  if (bodies.some((b) => String(b || "").includes(NEEDS_HUMAN_MARKER))) {
    return "unlabelled-handoff"; // ML-009: handed off, label dropped
  }

  const updated = Date.parse(updatedAt ?? "");
  const created = Date.parse(createdAt ?? updatedAt ?? "");
  if (Number.isNaN(updated)) return null; // unparseable → leave to the cadence

  const routed = countRouterCycles(bodies) > 0;
  if (routed) {
    return now - updated > staleHours * 3600_000 ? "stale-routed" : null;
  }
  // Never routed: only a violation once the PR has aged out of the scan's
  // recency window — inside the window the cadence still picks it up itself.
  const age = now - Math.max(updated, Number.isNaN(created) ? 0 : created);
  return age > windowDays * 86400_000 ? "never-routed" : null;
}

/** Hand-off comment for the three violation classes. Carries the hidden
 *  needs-human marker so the label logic (and the ML-009 guard) recognise it
 *  as an escalation, plus the Epic-019 reason marker — the sweep kind IS the
 *  reason code, reused verbatim (workforce/docs/pr-escalation-reasons.md v1). */
export function sweepHandoffBody(kind, { staleHours, windowDays }) {
  const reason =
    kind === "unlabelled-handoff"
      ? "handed off (a comment carries the hidden needs-human marker) but the label was dropped (ML-009)"
      : kind === "stale-routed"
        ? `routed for review but reached no terminal state (merged / hand-off) within ${staleHours}h`
        : `never picked up by the routing cadence within its ${windowDays}-day discovery window`;
  return [
    "**Autopilot sweep — terminal-state enforcement.**",
    "",
    `This PR was ${reason}. Escalating so the two-outcome contract holds: every PR in autopilot scope ends **merged** or **escalated to a human**.`,
    "",
    "Next step: the operator (or the next cadence run) re-drives the review cycle, or closes the PR.",
    "",
    "— pr-autopilot sweep (deterministic; see workforce/skills/pr-autopilot/SKILL.md)",
    "",
    NEEDS_HUMAN_MARKER,
    reasonMarker(kind),
  ].join("\n");
}

function arg(name, fallback) {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 && i + 1 < process.argv.length ? process.argv[i + 1] : fallback;
}

async function main() {
  const token = process.env.GITHUB_TOKEN || process.env.GH_TOKEN;
  const apply = process.argv.includes("--apply");
  const asJson = process.argv.includes("--json");
  const staleHours = Number(arg("stale-hours", String(DEFAULT_STALE_HOURS)));
  const windowDays = Number(arg("window-days", String(DEFAULT_WINDOW_DAYS)));
  let repo = arg("repo");
  const projectId = arg("project");

  if (!token) return die(1, "GITHUB_TOKEN (or GH_TOKEN) env is required");
  if (!repo && projectId) {
    try {
      const r = projectRepo(REPO_ROOT, projectId);
      repo = `${r.owner}/${r.repo}`;
    } catch (e) {
      return die(1, e.message);
    }
  }
  if (!repo || !/^[^/]+\/[^/]+$/.test(repo)) return die(1, "--repo <owner>/<repo> (or --project <id>) is required");
  if (!Number.isFinite(staleHours) || staleHours <= 0) return die(1, `--stale-hours must be positive (got ${staleHours})`);
  if (!Number.isFinite(windowDays) || windowDays <= 0) return die(1, `--window-days must be positive (got ${windowDays})`);

  const gh = makeGh({ token, userAgent: "workforce-pr-autopilot-sweep" });

  let prs;
  try {
    const r = await gh("GET", `/repos/${repo}/pulls?state=open&per_page=100`);
    if (r.status !== 200 || !Array.isArray(r.json)) return die(3, `GET pulls → HTTP ${r.status}`);
    prs = r.json;
  } catch (e) {
    return die(3, e?.msg || e?.message || String(e));
  }

  const violations = [];
  for (const pr of prs) {
    let bodies = [];
    try {
      const [c, rv] = await Promise.all([
        gh("GET", `/repos/${repo}/issues/${pr.number}/comments?per_page=100`),
        gh("GET", `/repos/${repo}/pulls/${pr.number}/reviews?per_page=100`),
      ]);
      bodies = [
        ...(Array.isArray(c.json) ? c.json.map((x) => x.body) : []),
        ...(Array.isArray(rv.json) ? rv.json.map((x) => x.body) : []),
      ];
    } catch (e) {
      return die(3, `#${pr.number}: ${e?.msg || e?.message || String(e)}`);
    }
    const kind = classifySweep(
      {
        createdAt: pr.created_at,
        updatedAt: pr.updated_at,
        labels: Array.isArray(pr.labels) ? pr.labels.map((l) => l?.name) : [],
        bodies,
      },
      { staleHours, windowDays },
    );
    if (kind) violations.push({ number: pr.number, title: pr.title, url: pr.html_url, kind });
  }

  let failedApplies = 0;
  if (apply && violations.length > 0) {
    await ensureLabels(gh, repo, [ESCALATION_LABEL, ...new Set(violations.map((v) => reasonLabel(v.kind)))]);
    for (const v of violations) {
      // Every class gets the hand-off comment: it carries the hidden
      // needs-human marker plus the Epic-019 reason marker. An
      // unlabelled-handoff already has a hand-off comment, but not necessarily
      // a reason — the sweep's comment closes that telemetry gap too.
      const c = await gh("POST", `/repos/${repo}/issues/${v.number}/comments`, {
        body: sweepHandoffBody(v.kind, { staleHours, windowDays }),
      });
      if (c.status !== 201) {
        failedApplies++;
        console.error(`pr-autopilot-sweep: FAILED comment on #${v.number} → HTTP ${c.status}`);
        continue;
      }
      const l = await gh("POST", `/repos/${repo}/issues/${v.number}/labels`, { labels: [ESCALATION_LABEL, reasonLabel(v.kind)] });
      if (l.status === 200) console.error(`pr-autopilot-sweep: escalated #${v.number} (${v.kind})`);
      else {
        failedApplies++;
        console.error(`pr-autopilot-sweep: FAILED label on #${v.number} → HTTP ${l.status}`);
      }
    }
  }

  if (asJson) console.log(JSON.stringify({ repo, checked: prs.length, applied: apply, violations }, null, 2));
  if (violations.length === 0) {
    if (!asJson) console.error(`pr-autopilot-sweep: OK — ${prs.length} open PR(s), every one is terminal or in-cycle`);
    return 0;
  }
  if (!asJson) {
    console.error(
      `pr-autopilot-sweep: ${violations.length} PR(s) in a non-terminal state${apply ? " (escalated now)" : " (run with --apply to escalate)"}:`,
    );
    for (const v of violations) console.error(`  - #${v.number} [${v.kind}] ${v.title} — ${v.url}`);
  }
  if (apply) return failedApplies > 0 ? 2 : 0;
  return 2;
}

function die(code, msg) {
  console.error(`pr-autopilot-sweep: ${msg}`);
  return code;
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? "").href) {
  process.exit(await main());
}

// @ts-nocheck — the engine under test (pr-merge.mjs) is a dependency-free ESM
// script, not TS; vitest/esbuild imports it fine at runtime, and this suite is
// not shipped code. Discovered by workforce/lambdas/vitest.config.mjs
// (`include: ["../skills/**/*-tests.ts"]`), so `cd workforce/lambdas && npm test`
// (the CI step) runs it. Closes Sana's C1: the merge-gating predicate's
// regression net lives in the repo, not a session transcript (adr-0010).
import { describe, it, expect } from "vitest";
import {
  globToRegExp,
  resolveL0L1Paths,
  reviewerSignedOff,
  reviewerGreenMarker,
  countRouterCycles,
  W4_CYCLE_CAP,
  MIN_REVIEWERS,
  verifyMergeable,
  applyDecisions,
  prTouchesL0L1,
  ESCALATION_LABEL,
} from "./pr-merge.mjs";

/** Route a `${method} ${path}` string to a canned {status,json} response. */
function mockGh(routes) {
  const calls = [];
  const gh = async (method, path, body) => {
    calls.push({ method, path, body });
    for (const [re, resp] of routes) {
      if (re.test(`${method} ${path}`)) return typeof resp === "function" ? resp() : resp;
    }
    return { status: 404, json: {} };
  };
  gh.calls = calls;
  return gh;
}

const govDoc = (block) => ({
  status: 200,
  json: { encoding: "base64", content: Buffer.from(`# gov\n${block}\n`).toString("base64") },
});
const L0_BLOCK =
  "<!-- autopilot:l0l1-paths -->\n- docs/governance.md\n- docs/adr/**\n<!-- /autopilot:l0l1-paths -->";
const GREEN_CHECK = [{ name: "ci", status: "completed", conclusion: "success" }];
// A non-blocking lens review carries the exact structured green marker.
const DARIO_REVIEW = [{ state: "COMMENTED", body: `looks good\n\n${reviewerGreenMarker("dario")}` }];
// A merge needs a panel of ≥ MIN_REVIEWERS (operator directive 2026-06-29).
// PANEL + PANEL_REVIEWS is the canonical green-consensus fixture; each persona
// posts its own exact green marker.
const PANEL = ["dario", "ren", "mateo"];
const PANEL_REVIEWS = PANEL.map((slug) => ({ state: "COMMENTED", body: `looks good\n\n${reviewerGreenMarker(slug)}` }));

/** Standard happy-path route table, parameterised by the variable bits. */
const routes = (files, checks, reviews, comments = []) => [
  [/GET \/repos\/o\/r\/pulls\/1$/, { status: 200, json: { state: "open", mergeable: true, mergeable_state: "clean", head: { sha: "abc" }, base: { ref: "main" } } }],
